window.SRC_FILES={"src/app.json5":"{\r\n  \"app\": {\r\n    \"bundleName\": \"com.example.firstt\",\r\n    \"vendor\": \"example\",\r\n    \"versionCode\": 1000000,\r\n    \"versionName\": \"1.0.0\",\r\n    \"icon\": \"$media:layered_image\",\r\n    \"label\": \"$string:app_name\"\r\n  }\r\n}\r\n","src/build-profile.json5":"{\r\n  \"app\": {\r\n    \"signingConfigs\": [\r\n      {\r\n        \"name\": \"default\",\r\n        \"type\": \"HarmonyOS\",\r\n        \"material\": {\r\n          \"storeFile\": \"D:/key/ANTIMATTER.p12\",\r\n          \"storePassword\": \"0000001987A4BDCB194BB097692B61A85F8E6DCCC0DCF3D3B696CE3185132C442343574578036C49E6\",\r\n          \"keyAlias\": \"infinty\",\r\n          \"keyPassword\": \"00000019F08E72577E0EBF0F89D0B6AF750D1FC39AF65C4D43E0B716EA42196D21C76AC4076646430A\",\r\n          \"signAlg\": \"SHA256withECDSA\",\r\n          \"profile\": \"D:/kuaibei03Release (1).p7b\",\r\n          \"certpath\": \"D:/fabu (1).cer\"\r\n        }\r\n      }\r\n    ],\r\n    \"products\": [\r\n      {\r\n        \"name\": \"default\",\r\n        \"signingConfig\": \"default\",\r\n        \"targetSdkVersion\": \"6.0.1(21)\",\r\n        \"compatibleSdkVersion\": \"6.0.0(20)\",\r\n        \"runtimeOS\": \"HarmonyOS\",\r\n        \"buildOption\": {\r\n          \"strictMode\": {\r\n            \"caseSensitiveCheck\": true,\r\n            \"useNormalizedOHMUrl\": true\r\n          }\r\n        }\r\n      }\r\n    ],\r\n    \"buildModeSet\": [\r\n      {\r\n        \"name\": \"debug\",\r\n      },\r\n      {\r\n        \"name\": \"release\"\r\n      }\r\n    ]\r\n  },\r\n  \"modules\": [\r\n    {\r\n      \"name\": \"entry\",\r\n      \"srcPath\": \"./entry\",\r\n      \"targets\": [\r\n        {\r\n          \"name\": \"default\",\r\n          \"applyToProducts\": [\r\n            \"default\"\r\n          ]\r\n        }\r\n      ]\r\n    }\r\n  ]\r\n}","src/entry-string.json":"{\n  \"string\": [\n    {\n      \"name\": \"module_desc\",\n      \"value\": \"快背单词\"\n    },\n    {\n      \"name\": \"EntryAbility_desc\",\n      \"value\": \"快背单词\"\n    },\n    {\n      \"name\": \"EntryAbility_label\",\n      \"value\": \"快背单词\"\n    }\n  ]\n}","src/ets/common/AppConstants.ets":"import { BuiltInBookDef } from '../model/WordModel';\n\n// 应用全局常量：艾宾浩斯间隔、持久化键名、内置词书清单\nexport class AppConstants {\n  static readonly EBBINGHAUS_DAYS: number[] = [1, 2, 4, 7, 15, 30];\n  static readonly MASTER_LEVEL: number = 6;\n\n  static readonly STORE_NAME: string = 'word_app_prefs';\n  static readonly KEY_SETTINGS: string = 'user_settings';\n  static readonly KEY_CHECK_INS: string = 'check_ins';\n  static readonly KEY_REVIEW_RECORDS: string = 'review_records';\n  static readonly KEY_WORD_PROGRESS: string = 'word_progress_map';\n  static readonly KEY_IMPORTED_BOOKS: string = 'imported_books';\n  static readonly KEY_ACHIEVEMENTS: string = 'achievements';\n  static readonly KEY_QUIZ_COUNT: string = 'quiz_count';\n\n  static readonly DEFAULT_DAILY_TARGET: number = 20;\n  static readonly DEFAULT_FONT_SCALE: number = 1.0;\n  static readonly MIN_FONT_SCALE: number = 0.9;\n  static readonly MAX_FONT_SCALE: number = 1.4;\n  static readonly MAX_DAILY_TARGET: number = 200;\n\n  static readonly QUIZ_COUNTS: number[] = [5, 10, 20];\n  static readonly QUIZ_OPTION_COUNT: number = 4;\n\n  static readonly BUILT_IN_BOOKS: BuiltInBookDef[] = [\n    {\n      id: 'gaokao',\n      name: '高考核心词汇',\n      description: '高中英语必备单词',\n      rawFile: 'words/gaokao.json',\n    },\n    {\n      id: 'cet4',\n      name: '四级核心词汇',\n      description: '大学英语四级必备词汇',\n      rawFile: 'words/cet4.json',\n    },\n    {\n      id: 'kaoyan',\n      name: '考研核心词汇',\n      description: '研究生考试必备单词',\n      rawFile: 'words/kaoyan.json',\n    },\n  ];\n}\n","src/ets/common/AppTheme.ets":"// 公共样式常量：间距、圆角、阴影、渐变与多色彩统一管理\nexport class AppTheme {\n  static readonly PAGE_PADDING: number = 16;\n  static readonly CARD_RADIUS: number = 18;\n  static readonly BUTTON_RADIUS: number = 14;\n  static readonly SPACE_SMALL: number = 8;\n  static readonly SPACE_NORMAL: number = 12;\n  static readonly SPACE_LARGE: number = 16;\n\n  static cardShadow(): ShadowOptions {\n    const shadow: ShadowOptions = {\n      radius: 12,\n      color: $r('app.color.card_shadow'),\n      offsetX: 0,\n      offsetY: 4,\n    };\n    return shadow;\n  }\n\n  // 主色渐变：用于首页欢迎卡等强调区域\n  static primaryGradient(): LinearGradientOptions {\n    const stops: [ResourceColor, number][] = [\n      [$r('app.color.primary_gradient_start'), 0],\n      [$r('app.color.primary_gradient_end'), 1],\n    ];\n    const options: LinearGradientOptions = {\n      angle: 135,\n      colors: stops,\n    };\n    return options;\n  }\n\n  // 底部五个 Tab 各自的强调色\n  static tabAccent(index: number): Resource {\n    if (index === 1) {\n      return $r('app.color.success');\n    }\n    if (index === 2) {\n      return $r('app.color.accent_orange');\n    }\n    if (index === 3) {\n      return $r('app.color.accent_purple');\n    }\n    if (index === 4) {\n      return $r('app.color.accent_teal');\n    }\n    return $r('app.color.primary');\n  }\n\n  static tabContainer(index: number): Resource {\n    if (index === 1) {\n      return $r('app.color.success_container');\n    }\n    if (index === 2) {\n      return $r('app.color.accent_orange_container');\n    }\n    if (index === 3) {\n      return $r('app.color.accent_purple_container');\n    }\n    if (index === 4) {\n      return $r('app.color.accent_teal_container');\n    }\n    return $r('app.color.primary_container');\n  }\n\n  // 自测三种模式选中色：蓝 / 紫 / 橙\n  static modeAccent(mode: number): Resource {\n    if (mode === 1) {\n      return $r('app.color.accent_purple');\n    }\n    if (mode === 2) {\n      return $r('app.color.accent_orange');\n    }\n    return $r('app.color.primary');\n  }\n}\n","src/ets/common/DateUtils.ets":"// 北京时间日期工具：统一以 UTC+8 自然日作为签到与复习调度基准\n\nexport interface CalendarCell {\n  dateKey: string;\n  day: number;\n  inMonth: boolean;\n  isToday: boolean;\n}\n\nexport interface DayLearnCount {\n  dateKey: string;\n  label: string;\n  count: number;\n}\n\nconst BEIJING_OFFSET_MS: number = 8 * 60 * 60 * 1000;\n\nfunction pad2(value: number): string {\n  return value < 10 ? `0${value}` : `${value}`;\n}\n\n// 返回北京时间对应的 Date 对象（其 UTC 字段即北京时间字段）\nfunction beijingDate(baseTime: number): Date {\n  return new Date(baseTime + BEIJING_OFFSET_MS);\n}\n\nexport function formatDateKey(date: Date): string {\n  return `${date.getUTCFullYear()}-${pad2(date.getUTCMonth() + 1)}-${pad2(date.getUTCDate())}`;\n}\n\nexport function todayKey(): string {\n  return formatDateKey(beijingDate(Date.now()));\n}\n\nexport function dateKeyFromTime(time: number): string {\n  return formatDateKey(beijingDate(time));\n}\n\n// 在日期键上加减天数\nexport function addDays(dateKey: string, days: number): string {\n  const parts: string[] = dateKey.split('-');\n  const year: number = Number(parts[0]);\n  const month: number = Number(parts[1]);\n  const day: number = Number(parts[2]);\n  const utc: Date = new Date(Date.UTC(year, month - 1, day));\n  const next: Date = new Date(utc.getTime() + days * 24 * 60 * 60 * 1000);\n  return formatDateKey(next);\n}\n\n// 两个日期键相差的天数（keyA - keyB）\nexport function diffDays(keyA: string, keyB: string): number {\n  const partsA: string[] = keyA.split('-');\n  const partsB: string[] = keyB.split('-');\n  const timeA: number = Date.UTC(Number(partsA[0]), Number(partsA[1]) - 1, Number(partsA[2]));\n  const timeB: number = Date.UTC(Number(partsB[0]), Number(partsB[1]) - 1, Number(partsB[2]));\n  return Math.round((timeA - timeB) / (24 * 60 * 60 * 1000));\n}\n\nexport function isYesterday(lastKey: string, today: string): boolean {\n  return diffDays(today, lastKey) === 1;\n}\n\nexport function isSameDay(keyA: string, keyB: string): boolean {\n  return keyA === keyB;\n}\n\n// 生成某月日历网格（周日开头，6 行 × 7 列 = 42 格）\nexport function buildMonthCalendar(year: number, month: number): CalendarCell[] {\n  const cells: CalendarCell[] = [];\n  const today: string = todayKey();\n  const firstOfMonth: Date = new Date(Date.UTC(year, month, 1));\n  const firstWeekDay: number = firstOfMonth.getUTCDay();\n  const gridStart: Date = new Date(firstOfMonth.getTime() - firstWeekDay * 24 * 60 * 60 * 1000);\n  for (let i: number = 0; i < 42; i++) {\n    const cellDate: Date = new Date(gridStart.getTime() + i * 24 * 60 * 60 * 1000);\n    const key: string = formatDateKey(cellDate);\n    const cell: CalendarCell = {\n      dateKey: key,\n      day: cellDate.getUTCDate(),\n      inMonth: cellDate.getUTCMonth() === month,\n      isToday: key === today,\n    };\n    cells.push(cell);\n  }\n  return cells;\n}\n\nexport function currentBeijingYearMonth(): number[] {\n  const now: Date = beijingDate(Date.now());\n  return [now.getUTCFullYear(), now.getUTCMonth()];\n}\n\n// 近 7 天日期键（含今天，旧 → 新）\nexport function recent7DayKeys(): string[] {\n  const today: string = todayKey();\n  const keys: string[] = [];\n  for (let i: number = 6; i >= 0; i--) {\n    keys.push(addDays(today, -i));\n  }\n  return keys;\n}\n\nexport function weekdayLabel(dateKey: string): string {\n  const parts: string[] = dateKey.split('-');\n  const date: Date = new Date(Date.UTC(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2])));\n  const labels: string[] = ['日', '一', '二', '三', '四', '五', '六'];\n  return labels[date.getUTCDay()];\n}\n","src/ets/entryability/EntryAbility.ets":"import { AbilityConstant, ConfigurationConstant, UIAbility, Want } from '@kit.AbilityKit';\r\nimport { hilog } from '@kit.PerformanceAnalysisKit';\r\nimport { window } from '@kit.ArkUI';\r\n\r\nconst DOMAIN = 0x0000;\r\n\r\nexport default class EntryAbility extends UIAbility {\r\n  onCreate(want: Want, launchParam: AbilityConstant.LaunchParam): void {\r\n    try {\r\n      this.context.getApplicationContext().setColorMode(ConfigurationConstant.ColorMode.COLOR_MODE_NOT_SET);\r\n    } catch (err) {\r\n      hilog.error(DOMAIN, 'testTag', 'Failed to set colorMode. Cause: %{public}s', JSON.stringify(err));\r\n    }\r\n    hilog.info(DOMAIN, 'testTag', '%{public}s', 'Ability onCreate');\r\n  }\r\n\r\n  onDestroy(): void {\r\n    hilog.info(DOMAIN, 'testTag', '%{public}s', 'Ability onDestroy');\r\n  }\r\n\r\n  onWindowStageCreate(windowStage: window.WindowStage): void {\r\n    // Main window is created, set main page for this ability\r\n    hilog.info(DOMAIN, 'testTag', '%{public}s', 'Ability onWindowStageCreate');\r\n\r\n    windowStage.loadContent('pages/Index', (err) => {\r\n      if (err.code) {\r\n        hilog.error(DOMAIN, 'testTag', 'Failed to load the content. Cause: %{public}s', JSON.stringify(err));\r\n        return;\r\n      }\r\n      hilog.info(DOMAIN, 'testTag', 'Succeeded in loading the content.');\r\n    });\r\n  }\r\n\r\n  onWindowStageDestroy(): void {\r\n    // Main window is destroyed, release UI related resources\r\n    hilog.info(DOMAIN, 'testTag', '%{public}s', 'Ability onWindowStageDestroy');\r\n  }\r\n\r\n  onForeground(): void {\r\n    // Ability has brought to foreground\r\n    hilog.info(DOMAIN, 'testTag', '%{public}s', 'Ability onForeground');\r\n  }\r\n\r\n  onBackground(): void {\r\n    // Ability has back to background\r\n    hilog.info(DOMAIN, 'testTag', '%{public}s', 'Ability onBackground');\r\n  }\r\n}","src/ets/entrybackupability/EntryBackupAbility.ets":"import { hilog } from '@kit.PerformanceAnalysisKit';\r\nimport { BackupExtensionAbility, BundleVersion } from '@kit.CoreFileKit';\r\n\r\nconst DOMAIN = 0x0000;\r\n\r\nexport default class EntryBackupAbility extends BackupExtensionAbility {\r\n  async onBackup() {\r\n    hilog.info(DOMAIN, 'testTag', 'onBackup ok');\r\n    await Promise.resolve();\r\n  }\r\n\r\n  async onRestore(bundleVersion: BundleVersion) {\r\n    hilog.info(DOMAIN, 'testTag', 'onRestore ok %{public}s', JSON.stringify(bundleVersion));\r\n    await Promise.resolve();\r\n  }\r\n}","src/ets/model/AchievementModel.ets":"// 成就系统数据模型：里程碑定义与解锁记录\n\nexport interface AchievementDef {\n  id: string;\n  title: string;\n  description: string;\n  icon: string;\n  category: string;\n  threshold: number;\n}\n\nexport interface AchievementState {\n  unlockedIds: string[];\n}\n\nexport function createAchievementState(): AchievementState {\n  const state: AchievementState = {\n    unlockedIds: [],\n  };\n  return state;\n}\n\n// 成就定义表：按类型分组，阈值递增\nexport const ACHIEVEMENT_DEFS: AchievementDef[] = [\n  // 掌握单词数\n  { id: 'master_10', title: '初窥门径', description: '掌握 10 个单词', icon: '🌱', category: 'mastered', threshold: 10 },\n  { id: 'master_50', title: '渐入佳境', description: '掌握 50 个单词', icon: '🌿', category: 'mastered', threshold: 50 },\n  { id: 'master_100', title: '百词斩', description: '掌握 100 个单词', icon: '🌳', category: 'mastered', threshold: 100 },\n  { id: 'master_300', title: '词汇大师', description: '掌握 300 个单词', icon: '🏆', category: 'mastered', threshold: 300 },\n  // 连续签到\n  { id: 'streak_3', title: '三日打卡', description: '连续签到 3 天', icon: '🔥', category: 'streak', threshold: 3 },\n  { id: 'streak_7', title: '一周坚持', description: '连续签到 7 天', icon: '⚡', category: 'streak', threshold: 7 },\n  { id: 'streak_21', title: '习惯养成', description: '连续签到 21 天', icon: '💎', category: 'streak', threshold: 21 },\n  { id: 'streak_30', title: '月度达人', description: '连续签到 30 天', icon: '👑', category: 'streak', threshold: 30 },\n  // 累计复习次数\n  { id: 'review_100', title: '勤奋学子', description: '累计复习 100 次', icon: '📖', category: 'reviews', threshold: 100 },\n  { id: 'review_500', title: '孜孜不倦', description: '累计复习 500 次', icon: '📚', category: 'reviews', threshold: 500 },\n  { id: 'review_1000', title: '学海无涯', description: '累计复习 1000 次', icon: '🎓', category: 'reviews', threshold: 1000 },\n  // 自测完成次数\n  { id: 'quiz_10', title: '小试牛刀', description: '完成 10 次自测', icon: '✏️', category: 'quizzes', threshold: 10 },\n  { id: 'quiz_50', title: '测验能手', description: '完成 50 次自测', icon: '📝', category: 'quizzes', threshold: 50 },\n  { id: 'quiz_100', title: '考试达人', description: '完成 100 次自测', icon: '🎯', category: 'quizzes', threshold: 100 },\n];\n","src/ets/model/WordModel.ets":"// 单词数据模型层：词书、单词、学习进度、复习记录、签到记录、用户设置\n\nexport interface WordItem {\n  id: string;\n  word: string;\n  phonetic: string;\n  meaning: string;\n  example: string;\n}\n\nexport interface WordBookItem {\n  id: string;\n  name: string;\n  description: string;\n  isBuiltIn: boolean;\n  words: WordItem[];\n}\n\n// 单个单词的艾宾浩斯学习进度，按 bookId/word 维度持久化\nexport interface WordProgress {\n  ebbinghausLevel: number;\n  reviewCount: number;\n  mastered: boolean;\n  lastReviewDate: string;\n  nextReviewDate: string;\n}\n\nexport interface ReviewRecord {\n  id: string;\n  wordBookId: string;\n  word: string;\n  meaning: string;\n  wasCorrect: boolean;\n  reviewDate: string;\n  levelBefore: number;\n  levelAfter: number;\n}\n\nexport interface CheckInRecord {\n  dateKey: string;\n  streak: number;\n  learned: number;\n}\n\n// 0=跟随系统 1=浅色 2=深色\nexport interface UserSettings {\n  themeMode: number;\n  fontScale: number;\n  dailyTarget: number;\n  currentBookId: string;\n}\n\nexport interface BuiltInBookDef {\n  id: string;\n  name: string;\n  description: string;\n  rawFile: string;\n}\n\nexport function createWord(id: string, word: string, phonetic: string, meaning: string, example: string): WordItem {\n  const item: WordItem = {\n    id: id,\n    word: word,\n    phonetic: phonetic,\n    meaning: meaning,\n    example: example,\n  };\n  return item;\n}\n\nexport function createWordBook(id: string, name: string, description: string, isBuiltIn: boolean,\n  words: WordItem[]): WordBookItem {\n  const book: WordBookItem = {\n    id: id,\n    name: name,\n    description: description,\n    isBuiltIn: isBuiltIn,\n    words: words,\n  };\n  return book;\n}\n\nexport function createWordProgress(): WordProgress {\n  const progress: WordProgress = {\n    ebbinghausLevel: 0,\n    reviewCount: 0,\n    mastered: false,\n    lastReviewDate: '',\n    nextReviewDate: '',\n  };\n  return progress;\n}\n\nexport function createReviewRecord(id: string, wordBookId: string, word: string, meaning: string,\n  wasCorrect: boolean, reviewDate: string, levelBefore: number, levelAfter: number): ReviewRecord {\n  const record: ReviewRecord = {\n    id: id,\n    wordBookId: wordBookId,\n    word: word,\n    meaning: meaning,\n    wasCorrect: wasCorrect,\n    reviewDate: reviewDate,\n    levelBefore: levelBefore,\n    levelAfter: levelAfter,\n  };\n  return record;\n}\n\nexport function createCheckInRecord(dateKey: string, streak: number, learned: number): CheckInRecord {\n  const record: CheckInRecord = {\n    dateKey: dateKey,\n    streak: streak,\n    learned: learned,\n  };\n  return record;\n}\n\nexport function createDefaultSettings(currentBookId: string): UserSettings {\n  const settings: UserSettings = {\n    themeMode: 0,\n    fontScale: 1.0,\n    dailyTarget: 20,\n    currentBookId: currentBookId,\n  };\n  return settings;\n}\n\n// 进度快照复制，避免直接修改持久化缓存对象\nexport function cloneProgress(progress: WordProgress): WordProgress {\n  const clone: WordProgress = {\n    ebbinghausLevel: progress.ebbinghausLevel,\n    reviewCount: progress.reviewCount,\n    mastered: progress.mastered,\n    lastReviewDate: progress.lastReviewDate,\n    nextReviewDate: progress.nextReviewDate,\n  };\n  return clone;\n}\n","src/ets/pages/Index.ets":"// 应用入口页：异步初始化 + 底部 Tab 容器，一级页面均为自定义组件\nimport { ConfigurationConstant, common } from '@kit.AbilityKit';\nimport { hilog } from '@kit.PerformanceAnalysisKit';\nimport { AppConstants } from '../common/AppConstants';\nimport { AppTheme } from '../common/AppTheme';\nimport { UserSettings, WordBookItem } from '../model/WordModel';\nimport { AchievementDef } from '../model/AchievementModel';\nimport { AchievementService } from '../service/AchievementService';\nimport { CheckInService } from '../service/CheckInService';\nimport { QuizService } from '../service/QuizService';\nimport { ReviewSchedulerService } from '../service/ReviewSchedulerService';\nimport { StorageService } from '../service/StorageService';\nimport { TtsService } from '../service/TtsService';\nimport { WordBookService } from '../service/WordBookService';\nimport { HomePage } from '../view/HomePage';\nimport { QuizPage } from '../view/QuizPage';\nimport { SettingsPage } from '../view/SettingsPage';\nimport { StatsPage } from '../view/StatsPage';\nimport { StudyPage } from '../view/StudyPage';\n\nconst LOG_DOMAIN: number = 0x0000;\nconst TAG: string = 'Index';\n\n@Entry\n@Component\nstruct Index {\n  @State ready: boolean = false;\n  @State initError: string = '';\n  @State currentTab: number = 0;\n  @State books: WordBookItem[] = [];\n  @State currentBookId: string = '';\n  @State fontScale: number = AppConstants.DEFAULT_FONT_SCALE;\n  @State themeMode: number = 0;\n  @State dailyTarget: number = AppConstants.DEFAULT_DAILY_TARGET;\n  @State refreshTick: number = 0;\n  @State achievementPopup: string = '';\n\n  private tabController: TabsController = new TabsController();\n\n  aboutToAppear(): void {\n    this.initApp();\n  }\n\n  private async initApp(): Promise<void> {\n    try {\n      const context: common.UIAbilityContext =\n        this.getUIContext().getHostContext() as common.UIAbilityContext;\n      await StorageService.getInstance().init(context);\n      await WordBookService.getInstance().init(context);\n      await CheckInService.getInstance().init();\n      await ReviewSchedulerService.getInstance().init();\n      await AchievementService.getInstance().init();\n      await QuizService.getInstance().init();\n      // TTS 初始化含音色下载，放后台不阻塞启动；speak 内部会检查 ready 状态\n      TtsService.getInstance().init().catch((err: Error) => {\n        hilog.error(0x0000, 'Index', 'tts init background failed: %{public}s', err.message);\n      });\n\n      const settings: UserSettings = await StorageService.getInstance().loadSettings();\n      this.applyThemeMode(settings.themeMode, context);\n\n      let bookId: string = settings.currentBookId;\n      if (WordBookService.getInstance().getBook(bookId) === undefined) {\n        bookId = AppConstants.BUILT_IN_BOOKS[0].id;\n      }\n      this.books = WordBookService.getInstance().getAllBooks();\n      this.currentBookId = bookId;\n      this.fontScale = settings.fontScale;\n      this.themeMode = settings.themeMode;\n      this.dailyTarget = settings.dailyTarget;\n      this.initError = '';\n      this.ready = true;\n      hilog.info(LOG_DOMAIN, TAG, 'app initialized, books: %{public}d', this.books.length);\n    } catch (err) {\n      this.initError = err instanceof Error ? err.message : '应用初始化失败，请重试';\n      hilog.error(LOG_DOMAIN, TAG, 'init failed: %{public}s', JSON.stringify(err));\n    }\n  }\n\n  private applyThemeMode(mode: number, context: common.UIAbilityContext): void {\n    try {\n      const appContext: common.ApplicationContext = context.getApplicationContext();\n      if (mode === 1) {\n        appContext.setColorMode(ConfigurationConstant.ColorMode.COLOR_MODE_LIGHT);\n      } else if (mode === 2) {\n        appContext.setColorMode(ConfigurationConstant.ColorMode.COLOR_MODE_DARK);\n      } else {\n        appContext.setColorMode(ConfigurationConstant.ColorMode.COLOR_MODE_NOT_SET);\n      }\n    } catch (err) {\n      hilog.error(LOG_DOMAIN, TAG, 'applyThemeMode failed: %{public}s', JSON.stringify(err));\n    }\n  }\n\n  private switchTab(index: number): void {\n    this.currentTab = index;\n    this.tabController.changeIndex(index);\n    this.notifyDataChanged();\n  }\n\n  private notifyDataChanged(): void {\n    this.refreshTick += 1;\n    this.checkAchievements();\n  }\n\n  private async checkAchievements(): Promise<void> {\n    const scheduler: ReviewSchedulerService = ReviewSchedulerService.getInstance();\n    const mastered: number = scheduler.getMasteredCount(this.currentBookId);\n    const streak: number = CheckInService.getInstance().getCurrentStreak();\n    const reviews: number = scheduler.getTotalReviewCount();\n    const quizzes: number = QuizService.getInstance().getQuizCount();\n    await AchievementService.getInstance().checkAndUnlock(mastered, streak, reviews, quizzes);\n    const newly: AchievementDef[] = AchievementService.getInstance().popNewlyUnlocked();\n    if (newly.length > 0) {\n      const first: AchievementDef = newly[0];\n      this.achievementPopup = `${first.icon} 解锁成就：${first.title}`;\n    }\n  }\n\n  private async persistSettings(): Promise<void> {\n    const settings: UserSettings = {\n      themeMode: this.themeMode,\n      fontScale: this.fontScale,\n      dailyTarget: this.dailyTarget,\n      currentBookId: this.currentBookId,\n    };\n    await StorageService.getInstance().saveSettings(settings);\n  }\n\n  private async switchBook(bookId: string): Promise<void> {\n    this.currentBookId = bookId;\n    await this.persistSettings();\n    this.notifyDataChanged();\n  }\n\n  private async onSettingsChanged(settings: UserSettings): Promise<void> {\n    this.themeMode = settings.themeMode;\n    this.fontScale = settings.fontScale;\n    this.dailyTarget = settings.dailyTarget;\n    if (settings.currentBookId.length > 0) {\n      this.currentBookId = settings.currentBookId;\n    }\n    await StorageService.getInstance().saveSettings(settings);\n    this.notifyDataChanged();\n  }\n\n  private onBooksChanged(): void {\n    this.books = WordBookService.getInstance().getAllBooks();\n    // 主动驱动首页词书列表刷新，不依赖 Tab 切换兜底\n    this.notifyDataChanged();\n  }\n\n  private async onDataReset(): Promise<void> {\n    this.ready = false;\n    this.initError = '';\n    await this.initApp();\n  }\n\n  private retry(): void {\n    this.initError = '';\n    this.initApp();\n  }\n\n  @Builder\n  buildTabBar(title: string, index: number) {\n    Column() {\n      Column() {\n        Row({ space: 5 }) {\n          if (this.currentTab === index) {\n            Column()\n              .width(6)\n              .height(6)\n              .borderRadius(999)\n              .backgroundColor(AppTheme.tabAccent(index))\n          }\n          Text(title)\n            .fontSize(13)\n            .fontWeight(this.currentTab === index ? FontWeight.Bold : FontWeight.Normal)\n            .fontColor(this.currentTab === index\n              ? AppTheme.tabAccent(index) : $r('app.color.text_secondary'))\n        }\n      }\n      .padding({ left: 14, right: 14, top: 6, bottom: 6 })\n      .borderRadius(999)\n      .backgroundColor(this.currentTab === index\n        ? AppTheme.tabContainer(index) : Color.Transparent)\n    }\n    .width('100%')\n    .height('100%')\n    .justifyContent(FlexAlign.Center)\n    .backgroundColor($r('app.color.nav_background'))\n  }\n\n  @Builder\n  buildLoading() {\n    Column({ space: 14 }) {\n      LoadingProgress()\n        .width(52)\n        .height(52)\n        .color($r('app.color.primary'))\n      Text('正在加载词书与学习数据…')\n        .fontSize(14)\n        .fontColor($r('app.color.text_secondary'))\n    }\n    .width('100%')\n    .height('100%')\n    .justifyContent(FlexAlign.Center)\n  }\n\n  @Builder\n  buildError() {\n    Column({ space: 14 }) {\n      Text('加载失败')\n        .fontSize(20)\n        .fontWeight(FontWeight.Bold)\n        .fontColor($r('app.color.text_main'))\n      Text(this.initError)\n        .fontSize(14)\n        .fontColor($r('app.color.text_secondary'))\n        .textAlign(TextAlign.Center)\n        .padding({ left: 32, right: 32 })\n      Button('重试')\n        .width(160)\n        .height(44)\n        .backgroundColor($r('app.color.primary'))\n        .fontColor($r('app.color.on_primary'))\n        .onClick(() => {\n          this.retry();\n        })\n    }\n    .width('100%')\n    .height('100%')\n    .justifyContent(FlexAlign.Center)\n  }\n\n  @Builder\n  buildMain() {\n    Tabs({ barPosition: BarPosition.End, controller: this.tabController }) {\n      TabContent() {\n        HomePage({\n          fontScale: this.fontScale,\n          currentBookId: this.currentBookId,\n          dailyTarget: this.dailyTarget,\n          refreshTick: this.refreshTick,\n          onSwitchBook: (bookId: string) => {\n            this.switchBook(bookId);\n          },\n          onGoStudy: () => {\n            this.switchTab(1);\n          },\n          onGoQuiz: () => {\n            this.switchTab(2);\n          },\n          onDataChanged: () => {\n            this.notifyDataChanged();\n          },\n        })\n      }\n      .tabBar(this.buildTabBar('首页', 0))\n\n      TabContent() {\n        StudyPage({\n          fontScale: this.fontScale,\n          dailyTarget: this.dailyTarget,\n          currentBookId: this.currentBookId,\n          refreshTick: this.refreshTick,\n          onDataChanged: () => {\n            this.notifyDataChanged();\n          },\n        })\n      }\n      .tabBar(this.buildTabBar('背词', 1))\n\n      TabContent() {\n        QuizPage({\n          fontScale: this.fontScale,\n          currentBookId: this.currentBookId,\n          onDataChanged: () => {\n            this.notifyDataChanged();\n          },\n        })\n      }\n      .tabBar(this.buildTabBar('自测', 2))\n\n      TabContent() {\n        StatsPage({\n          fontScale: this.fontScale,\n          currentBookId: this.currentBookId,\n          refreshTick: this.refreshTick,\n        })\n      }\n      .tabBar(this.buildTabBar('统计', 3))\n\n      TabContent() {\n        SettingsPage({\n          currentBookId: this.currentBookId,\n          themeMode: this.themeMode,\n          fontScale: this.fontScale,\n          dailyTarget: this.dailyTarget,\n          onSettingsChanged: (settings: UserSettings) => {\n            this.onSettingsChanged(settings);\n          },\n          onBooksChanged: () => {\n            this.onBooksChanged();\n          },\n          onDataReset: () => {\n            this.onDataReset();\n          },\n        })\n      }\n      .tabBar(this.buildTabBar('设置', 4))\n    }\n    .scrollable(false)\n    .barHeight(56)\n    .barMode(BarMode.Fixed)\n    .backgroundColor($r('app.color.page_background'))\n    .onChange((index: number) => {\n      this.currentTab = index;\n      this.notifyDataChanged();\n    })\n  }\n\n  build() {\n    Stack() {\n      Column() {\n        if (this.ready) {\n          this.buildMain()\n        } else if (this.initError.length > 0) {\n          this.buildError()\n        } else {\n          this.buildLoading()\n        }\n      }\n      .width('100%')\n      .height('100%')\n      .backgroundColor($r('app.color.page_background'))\n\n      if (this.achievementPopup.length > 0) {\n        Row({ space: 8 }) {\n          Text(this.achievementPopup)\n            .fontSize(14)\n            .fontWeight(FontWeight.Bold)\n            .fontColor($r('app.color.text_on_color'))\n        }\n        .padding({ left: 20, right: 20, top: 12, bottom: 12 })\n        .borderRadius(999)\n        .backgroundColor($r('app.color.accent_purple'))\n        .shadow(AppTheme.cardShadow())\n        .margin({ top: 48 })\n        .onClick(() => {\n          this.achievementPopup = '';\n        })\n      }\n    }\n    .width('100%')\n    .height('100%')\n  }\n}\n","src/ets/service/AchievementService.ets":"// 成就服务：检测解锁条件、持久化解锁状态、提供查询\nimport { hilog } from '@kit.PerformanceAnalysisKit';\nimport { AppConstants } from '../common/AppConstants';\nimport {\n  ACHIEVEMENT_DEFS,\n  AchievementDef,\n  AchievementState,\n  createAchievementState,\n} from '../model/AchievementModel';\nimport { StorageService } from './StorageService';\n\nconst LOG_DOMAIN: number = 0x0007;\nconst TAG: string = 'AchievementService';\n\nexport interface AchievementView {\n  def: AchievementDef;\n  unlocked: boolean;\n}\n\nexport class AchievementService {\n  private static instance: AchievementService | null = null;\n  private state: AchievementState = createAchievementState();\n  private newlyUnlocked: AchievementDef[] = [];\n\n  static getInstance(): AchievementService {\n    if (AchievementService.instance === null) {\n      AchievementService.instance = new AchievementService();\n    }\n    return AchievementService.instance;\n  }\n\n  async init(): Promise<void> {\n    this.state = await this.loadState();\n    hilog.info(LOG_DOMAIN, TAG, 'init, unlocked: %{public}d', this.state.unlockedIds.length);\n  }\n\n  private async loadState(): Promise<AchievementState> {\n    const raw: string = await StorageService.getInstance().readAchievementData();\n    if (raw.length === 0) {\n      return createAchievementState();\n    }\n    try {\n      const parsed: AchievementState = JSON.parse(raw) as AchievementState;\n      const ids: string[] = Array.isArray(parsed.unlockedIds) ? parsed.unlockedIds : [];\n      const state: AchievementState = {\n        unlockedIds: ids.filter((id: string) => typeof id === 'string' && id.length > 0),\n      };\n      return state;\n    } catch (err) {\n      hilog.error(LOG_DOMAIN, TAG, 'loadState failed: %{public}s', JSON.stringify(err));\n      return createAchievementState();\n    }\n  }\n\n  private async saveState(): Promise<void> {\n    await StorageService.getInstance().writeAchievementData(JSON.stringify(this.state));\n  }\n\n  isUnlocked(id: string): boolean {\n    return this.state.unlockedIds.indexOf(id) >= 0;\n  }\n\n  getUnlockedCount(): number {\n    return this.state.unlockedIds.length;\n  }\n\n  getTotalCount(): number {\n    return ACHIEVEMENT_DEFS.length;\n  }\n\n  getAllAchievements(): AchievementView[] {\n    const views: AchievementView[] = [];\n    for (let i: number = 0; i < ACHIEVEMENT_DEFS.length; i++) {\n      const def: AchievementDef = ACHIEVEMENT_DEFS[i];\n      const view: AchievementView = {\n        def: def,\n        unlocked: this.isUnlocked(def.id),\n      };\n      views.push(view);\n    }\n    return views;\n  }\n\n  // 返回上次检查后新解锁的成就，用于 UI 提示\n  popNewlyUnlocked(): AchievementDef[] {\n    const result: AchievementDef[] = this.newlyUnlocked;\n    this.newlyUnlocked = [];\n    return result;\n  }\n\n  // 核心检测：根据当前指标值判定是否解锁新成就\n  async checkAndUnlock(masteredCount: number, streak: number, totalReviews: number, quizCount: number): Promise<void> {\n    const metrics: Record<string, number> = {};\n    metrics['mastered'] = masteredCount;\n    metrics['streak'] = streak;\n    metrics['reviews'] = totalReviews;\n    metrics['quizzes'] = quizCount;\n\n    let changed: boolean = false;\n    for (let i: number = 0; i < ACHIEVEMENT_DEFS.length; i++) {\n      const def: AchievementDef = ACHIEVEMENT_DEFS[i];\n      if (this.isUnlocked(def.id)) {\n        continue;\n      }\n      const value: number = metrics[def.category] !== undefined ? metrics[def.category] : 0;\n      if (value >= def.threshold) {\n        this.state.unlockedIds.push(def.id);\n        this.newlyUnlocked.push(def);\n        changed = true;\n        hilog.info(LOG_DOMAIN, TAG, 'unlocked: %{public}s', def.id);\n      }\n    }\n    if (changed) {\n      await this.saveState();\n    }\n  }\n}\n","src/ets/service/CheckInService.ets":"// 签到服务：北京时间自然日签到、连续 streak 计算、签到记录持久化\nimport { hilog } from '@kit.PerformanceAnalysisKit';\nimport { CheckInRecord, createCheckInRecord } from '../model/WordModel';\nimport { isYesterday, todayKey } from '../common/DateUtils';\nimport { StorageService } from './StorageService';\n\nconst LOG_DOMAIN: number = 0x0003;\nconst TAG: string = 'CheckInService';\n\nexport class CheckInService {\n  private static instance: CheckInService | null = null;\n  private records: CheckInRecord[] = [];\n\n  static getInstance(): CheckInService {\n    if (CheckInService.instance === null) {\n      CheckInService.instance = new CheckInService();\n    }\n    return CheckInService.instance;\n  }\n\n  async init(): Promise<void> {\n    this.records = await StorageService.getInstance().loadCheckIns();\n  }\n\n  getRecords(): CheckInRecord[] {\n    return this.records;\n  }\n\n  private findLatestRecord(): CheckInRecord | undefined {\n    let latest: CheckInRecord | undefined = undefined;\n    for (let i: number = 0; i < this.records.length; i++) {\n      const current: CheckInRecord = this.records[i];\n      if (latest === undefined || current.dateKey > latest.dateKey) {\n        latest = current;\n      }\n    }\n    return latest;\n  }\n\n  hasCheckedInToday(): boolean {\n    const today: string = todayKey();\n    for (let i: number = 0; i < this.records.length; i++) {\n      if (this.records[i].dateKey === today) {\n        return true;\n      }\n    }\n    return false;\n  }\n\n  // 签到成功返回 true；同日重复签到返回 false\n  async checkIn(learnedCount: number): Promise<boolean> {\n    const today: string = todayKey();\n    if (this.hasCheckedInToday()) {\n      return false;\n    }\n    let streak: number = 1;\n    const latest: CheckInRecord | undefined = this.findLatestRecord();\n    if (latest !== undefined && isYesterday(latest.dateKey, today)) {\n      streak = latest.streak + 1;\n    }\n    const record: CheckInRecord = createCheckInRecord(today, streak, learnedCount);\n    this.records.push(record);\n    const saved: boolean = await StorageService.getInstance().saveCheckIns(this.records);\n    if (!saved) {\n      // 持久化失败回滚内存记录，保证内存与磁盘一致，避免按钮态卡死\n      this.records.pop();\n      hilog.error(LOG_DOMAIN, TAG, 'checkIn persist failed, rolled back');\n      return false;\n    }\n    return true;\n  }\n\n  // 当前连续签到天数：今日已签取今日 streak；昨日签过 streak 延续；断签为 0\n  getCurrentStreak(): number {\n    const today: string = todayKey();\n    const latest: CheckInRecord | undefined = this.findLatestRecord();\n    if (latest === undefined) {\n      return 0;\n    }\n    if (latest.dateKey === today || isYesterday(latest.dateKey, today)) {\n      return latest.streak;\n    }\n    return 0;\n  }\n\n  getTotalCheckInDays(): number {\n    return this.records.length;\n  }\n\n  getBestStreak(): number {\n    let best: number = 0;\n    for (let i: number = 0; i < this.records.length; i++) {\n      if (this.records[i].streak > best) {\n        best = this.records[i].streak;\n      }\n    }\n    return best;\n  }\n\n  // 更新今日签到记录中的学习词数（签到后学习的数据快照）\n  async updateTodayLearned(learnedCount: number): Promise<void> {\n    const today: string = todayKey();\n    for (let i: number = 0; i < this.records.length; i++) {\n      if (this.records[i].dateKey === today) {\n        this.records[i].learned = learnedCount;\n        await StorageService.getInstance().saveCheckIns(this.records);\n        return;\n      }\n    }\n  }\n\n  // 返回某年某月（month 从 0 开始）已签到的日期键集合\n  getMonthCheckInKeys(year: number, month: number): string[] {\n    const monthPart: string = month + 1 < 10 ? `0${month + 1}` : `${month + 1}`;\n    const prefix: string = `${year}-${monthPart}`;\n    const keys: string[] = [];\n    for (let i: number = 0; i < this.records.length; i++) {\n      if (this.records[i].dateKey.substring(0, 7) === prefix) {\n        keys.push(this.records[i].dateKey);\n      }\n    }\n    return keys;\n  }\n}\n","src/ets/service/QuizService.ets":"// 自测服务：随机抽题、4 选项打乱、按内容判定、错题收集、自测计数\nimport { AppConstants } from '../common/AppConstants';\nimport { WordItem } from '../model/WordModel';\nimport { ReviewSchedulerService } from './ReviewSchedulerService';\nimport { StorageService } from './StorageService';\nimport { WordBookService } from './WordBookService';\n\nexport const QUIZ_MODE_EN_TO_CN: number = 0;\nexport const QUIZ_MODE_CN_TO_EN: number = 1;\nexport const QUIZ_MODE_DICTATION: number = 2;\n\nexport interface QuizResult {\n  total: number;\n  correct: number;\n  wrong: number;\n  wrongWords: WordItem[];\n}\n\nfunction shuffleList<T>(list: T[]): T[] {\n  const result: T[] = list.slice(0);\n  for (let i: number = result.length - 1; i > 0; i--) {\n    const j: number = Math.floor(Math.random() * (i + 1));\n    const temp: T = result[i];\n    result[i] = result[j];\n    result[j] = temp;\n  }\n  return result;\n}\n\nexport class QuizService {\n  private static instance: QuizService | null = null;\n  private quizWords: WordItem[] = [];\n  private currentIndex: number = 0;\n  private mode: number = QUIZ_MODE_EN_TO_CN;\n  private wrongWords: WordItem[] = [];\n  private currentOptions: string[] = [];\n  private quizCount: number = 0;\n\n  static getInstance(): QuizService {\n    if (QuizService.instance === null) {\n      QuizService.instance = new QuizService();\n    }\n    return QuizService.instance;\n  }\n\n  async init(): Promise<void> {\n    this.quizCount = await StorageService.getInstance().loadQuizCount();\n  }\n\n  getQuizCount(): number {\n    return this.quizCount;\n  }\n\n  async incrementQuizCount(): Promise<void> {\n    this.quizCount += 1;\n    await StorageService.getInstance().saveQuizCount(this.quizCount);\n  }\n\n  startQuiz(bookId: string, mode: number, count: number): void {\n    this.mode = mode;\n    this.currentIndex = 0;\n    this.wrongWords = [];\n    this.currentOptions = [];\n\n    const allWords: WordItem[] = WordBookService.getInstance().getBookWords(bookId);\n    const scheduler: ReviewSchedulerService = ReviewSchedulerService.getInstance();\n    const learned: WordItem[] = [];\n    const fresh: WordItem[] = [];\n    for (let i: number = 0; i < allWords.length; i++) {\n      const reviewCount: number = scheduler.getProgress(bookId, allWords[i].word).reviewCount;\n      if (reviewCount > 0) {\n        learned.push(allWords[i]);\n      } else {\n        fresh.push(allWords[i]);\n      }\n    }\n    const pool: WordItem[] = learned.length > 0 ? learned : fresh;\n    const target: number = Math.min(count, pool.length);\n    this.quizWords = shuffleList(pool).slice(0, target);\n  }\n\n  getMode(): number {\n    return this.mode;\n  }\n\n  getTotal(): number {\n    return this.quizWords.length;\n  }\n\n  getIndex(): number {\n    return this.currentIndex;\n  }\n\n  isFinished(): boolean {\n    return this.currentIndex >= this.quizWords.length;\n  }\n\n  isLastQuestion(): boolean {\n    return this.quizWords.length > 0 && this.currentIndex >= this.quizWords.length - 1;\n  }\n\n  getCurrentWord(): WordItem | undefined {\n    if (this.isFinished()) {\n      return undefined;\n    }\n    return this.quizWords[this.currentIndex];\n  }\n\n  private correctAnswer(): string {\n    const word: WordItem | undefined = this.getCurrentWord();\n    if (word === undefined) {\n      return '';\n    }\n    if (this.mode === QUIZ_MODE_CN_TO_EN || this.mode === QUIZ_MODE_DICTATION) {\n      return word.word;\n    }\n    return word.meaning;\n  }\n\n  // 选择题选项：正确答案 + 3 个干扰项，整体打乱\n  getOptions(bookId: string): string[] {\n    const word: WordItem | undefined = this.getCurrentWord();\n    if (word === undefined) {\n      return [];\n    }\n    const answer: string = this.correctAnswer();\n    const allWords: WordItem[] = WordBookService.getInstance().getBookWords(bookId);\n    const distractors: string[] = [];\n    const shuffledOthers: WordItem[] = shuffleList(allWords);\n    for (let i: number = 0; i < shuffledOthers.length; i++) {\n      const candidate: WordItem = shuffledOthers[i];\n      if (candidate.word === word.word) {\n        continue;\n      }\n      const optionText: string = this.mode === QUIZ_MODE_EN_TO_CN ? candidate.meaning : candidate.word;\n      if (optionText === answer || distractors.indexOf(optionText) >= 0) {\n        continue;\n      }\n      distractors.push(optionText);\n      if (distractors.length >= AppConstants.QUIZ_OPTION_COUNT - 1) {\n        break;\n      }\n    }\n    const options: string[] = [answer];\n    for (let i: number = 0; i < distractors.length; i++) {\n      options.push(distractors[i]);\n    }\n    this.currentOptions = shuffleList(options);\n    return this.currentOptions;\n  }\n\n  // 按答案内容判定，与按钮位置无关；错题收集\n  checkAnswer(answer: string): boolean {\n    const word: WordItem | undefined = this.getCurrentWord();\n    if (word === undefined) {\n      return false;\n    }\n    let isCorrect: boolean = false;\n    if (this.mode === QUIZ_MODE_DICTATION || this.mode === QUIZ_MODE_CN_TO_EN) {\n      isCorrect = answer.trim().toLowerCase() === word.word.trim().toLowerCase();\n    } else {\n      isCorrect = answer.trim() === word.meaning.trim();\n    }\n    if (!isCorrect) {\n      let exists: boolean = false;\n      for (let i: number = 0; i < this.wrongWords.length; i++) {\n        if (this.wrongWords[i].word === word.word) {\n          exists = true;\n          break;\n        }\n      }\n      if (!exists) {\n        this.wrongWords.push(word);\n      }\n    }\n    return isCorrect;\n  }\n\n  next(): void {\n    this.currentIndex += 1;\n    this.currentOptions = [];\n  }\n\n  getResult(): QuizResult {\n    const result: QuizResult = {\n      total: this.quizWords.length,\n      correct: this.quizWords.length - this.wrongWords.length,\n      wrong: this.wrongWords.length,\n      wrongWords: this.wrongWords.slice(0),\n    };\n    return result;\n  }\n}\n","src/ets/service/ReviewSchedulerService.ets":"// 复习调度服务：艾宾浩斯遗忘曲线、学习队列、复习记录与单词进度持久化\nimport { hilog } from '@kit.PerformanceAnalysisKit';\nimport { AppConstants } from '../common/AppConstants';\nimport {\n  DayLearnCount,\n  addDays,\n  dateKeyFromTime,\n  diffDays,\n  recent7DayKeys,\n  todayKey,\n  weekdayLabel,\n} from '../common/DateUtils';\nimport {\n  ReviewRecord,\n  WordItem,\n  WordProgress,\n  cloneProgress,\n  createReviewRecord,\n  createWordProgress,\n} from '../model/WordModel';\nimport { StorageService, ProgressEntry } from './StorageService';\nimport { WordBookService } from './WordBookService';\n\nconst LOG_DOMAIN: number = 0x0004;\nconst TAG: string = 'ReviewScheduler';\n\nfunction buildProgressKey(bookId: string, word: string): string {\n  return `${bookId}/${word}`;\n}\n\nfunction recordDateKey(isoDate: string): string {\n  try {\n    return dateKeyFromTime(new Date(isoDate).getTime());\n  } catch (err) {\n    return '';\n  }\n}\n\nexport class ReviewSchedulerService {\n  private static instance: ReviewSchedulerService | null = null;\n  private progressEntries: ProgressEntry[] = [];\n  private reviewRecords: ReviewRecord[] = [];\n\n  static getInstance(): ReviewSchedulerService {\n    if (ReviewSchedulerService.instance === null) {\n      ReviewSchedulerService.instance = new ReviewSchedulerService();\n    }\n    return ReviewSchedulerService.instance;\n  }\n\n  async init(): Promise<void> {\n    const storage: StorageService = StorageService.getInstance();\n    this.progressEntries = await storage.loadProgressEntries();\n    this.reviewRecords = await storage.loadReviewRecords();\n  }\n\n  private findEntryIndex(key: string): number {\n    for (let i: number = 0; i < this.progressEntries.length; i++) {\n      if (this.progressEntries[i].key === key) {\n        return i;\n      }\n    }\n    return -1;\n  }\n\n  getProgress(bookId: string, word: string): WordProgress {\n    const index: number = this.findEntryIndex(buildProgressKey(bookId, word));\n    if (index < 0) {\n      return createWordProgress();\n    }\n    return cloneProgress(this.progressEntries[index].progress);\n  }\n\n  // 处理一次复习判定：认识升级、不认识归零，持久化进度并写复习记录\n  async processReview(bookId: string, wordItem: WordItem, wasCorrect: boolean): Promise<void> {\n    const key: string = buildProgressKey(bookId, wordItem.word);\n    const current: WordProgress = this.getProgress(bookId, wordItem.word);\n    const levelBefore: number = current.ebbinghausLevel;\n    const today: string = todayKey();\n\n    let levelAfter: number = 0;\n    let nextReviewDate: string = '';\n    let mastered: boolean = false;\n    if (wasCorrect) {\n      levelAfter = Math.min(levelBefore + 1, AppConstants.MASTER_LEVEL);\n      const intervalIndex: number = Math.min(levelBefore, AppConstants.EBBINGHAUS_DAYS.length - 1);\n      nextReviewDate = addDays(today, AppConstants.EBBINGHAUS_DAYS[intervalIndex]);\n      mastered = levelAfter >= AppConstants.MASTER_LEVEL;\n    } else {\n      // 不认识：等级归零，当日到期需再次复习（计入\"今日待复习\"）\n      levelAfter = 0;\n      nextReviewDate = today;\n      mastered = false;\n    }\n\n    const updated: WordProgress = {\n      ebbinghausLevel: levelAfter,\n      reviewCount: current.reviewCount + 1,\n      mastered: mastered,\n      lastReviewDate: today,\n      nextReviewDate: mastered ? '' : nextReviewDate,\n    };\n    const entry: ProgressEntry = { key: key, progress: updated };\n    const existIndex: number = this.findEntryIndex(key);\n    if (existIndex >= 0) {\n      this.progressEntries[existIndex] = entry;\n    } else {\n      this.progressEntries.push(entry);\n    }\n\n    const record: ReviewRecord = createReviewRecord(\n      `r_${Date.now()}_${this.reviewRecords.length}`,\n      bookId,\n      wordItem.word,\n      wordItem.meaning,\n      wasCorrect,\n      new Date().toISOString(),\n      levelBefore,\n      levelAfter,\n    );\n    this.reviewRecords.push(record);\n\n    const storage: StorageService = StorageService.getInstance();\n    const progressSaved: boolean = await storage.saveProgressEntries(this.progressEntries);\n    const recordSaved: boolean = await storage.saveReviewRecords(this.reviewRecords);\n    if (!progressSaved || !recordSaved) {\n      hilog.error(LOG_DOMAIN, TAG, 'persist failed: progress=%{public}s record=%{public}s',\n        String(progressSaved), String(recordSaved));\n    }\n  }\n\n  // 今日到期待复习词（nextReviewDate <= 今天且未掌握）\n  getTodayReviewList(bookId: string): WordItem[] {\n    const words: WordItem[] = WordBookService.getInstance().getBookWords(bookId);\n    const today: string = todayKey();\n    const due: WordItem[] = [];\n    for (let i: number = 0; i < words.length; i++) {\n      const progress: WordProgress = this.getProgress(bookId, words[i].word);\n      if (progress.mastered) {\n        continue;\n      }\n      if (progress.nextReviewDate.length > 0 && progress.nextReviewDate <= today) {\n        due.push(words[i]);\n      }\n    }\n    return due;\n  }\n\n  getNewWordList(bookId: string, count: number): WordItem[] {\n    const words: WordItem[] = WordBookService.getInstance().getBookWords(bookId);\n    const fresh: WordItem[] = [];\n    for (let i: number = 0; i < words.length; i++) {\n      const progress: WordProgress = this.getProgress(bookId, words[i].word);\n      if (progress.reviewCount === 0) {\n        fresh.push(words[i]);\n        if (fresh.length >= count) {\n          break;\n        }\n      }\n    }\n    return fresh;\n  }\n\n  // 学习队列：到期复习词优先，新词补足至每日目标\n  getStudyQueue(bookId: string, dailyTarget: number): WordItem[] {\n    const due: WordItem[] = this.getTodayReviewList(bookId);\n    const queue: WordItem[] = due.slice(0);\n    if (queue.length >= dailyTarget) {\n      return queue.slice(0, dailyTarget);\n    }\n    const need: number = dailyTarget - queue.length;\n    const fresh: WordItem[] = this.getNewWordList(bookId, need);\n    for (let i: number = 0; i < fresh.length; i++) {\n      queue.push(fresh[i]);\n    }\n    return queue;\n  }\n\n  getMasteredCount(bookId: string): number {\n    const words: WordItem[] = WordBookService.getInstance().getBookWords(bookId);\n    let count: number = 0;\n    for (let i: number = 0; i < words.length; i++) {\n      if (this.getProgress(bookId, words[i].word).mastered) {\n        count += 1;\n      }\n    }\n    return count;\n  }\n\n  getDueCount(bookId: string): number {\n    return this.getTodayReviewList(bookId).length;\n  }\n\n  getNewWordCount(bookId: string): number {\n    const words: WordItem[] = WordBookService.getInstance().getBookWords(bookId);\n    let count: number = 0;\n    for (let i: number = 0; i < words.length; i++) {\n      if (this.getProgress(bookId, words[i].word).reviewCount === 0) {\n        count += 1;\n      }\n    }\n    return count;\n  }\n\n  getLearningCount(bookId: string): number {\n    const words: WordItem[] = WordBookService.getInstance().getBookWords(bookId);\n    let count: number = 0;\n    for (let i: number = 0; i < words.length; i++) {\n      const progress: WordProgress = this.getProgress(bookId, words[i].word);\n      if (progress.reviewCount > 0 && !progress.mastered) {\n        count += 1;\n      }\n    }\n    return count;\n  }\n\n  // 遗忘词：超过 7 天未复习且未掌握\n  getForgottenCount(bookId: string): number {\n    const words: WordItem[] = WordBookService.getInstance().getBookWords(bookId);\n    const today: string = todayKey();\n    let count: number = 0;\n    for (let i: number = 0; i < words.length; i++) {\n      const progress: WordProgress = this.getProgress(bookId, words[i].word);\n      if (progress.mastered || progress.lastReviewDate.length === 0) {\n        continue;\n      }\n      if (diffDays(today, progress.lastReviewDate) >= 7) {\n        count += 1;\n      }\n    }\n    return count;\n  }\n\n  getTodayLearnedCount(): number {\n    const today: string = todayKey();\n    let count: number = 0;\n    for (let i: number = 0; i < this.reviewRecords.length; i++) {\n      if (recordDateKey(this.reviewRecords[i].reviewDate) === today) {\n        count += 1;\n      }\n    }\n    return count;\n  }\n\n  // 近 7 天每日学习量（旧 → 新）\n  getRecent7DaysCounts(): DayLearnCount[] {\n    const keys: string[] = recent7DayKeys();\n    const result: DayLearnCount[] = [];\n    for (let i: number = 0; i < keys.length; i++) {\n      let count: number = 0;\n      for (let j: number = 0; j < this.reviewRecords.length; j++) {\n        if (recordDateKey(this.reviewRecords[j].reviewDate) === keys[i]) {\n          count += 1;\n        }\n      }\n      const dayCount: DayLearnCount = {\n        dateKey: keys[i],\n        label: weekdayLabel(keys[i]),\n        count: count,\n      };\n      result.push(dayCount);\n    }\n    return result;\n  }\n\n  getTotalReviewCount(): number {\n    return this.reviewRecords.length;\n  }\n\n  getCorrectCount(): number {\n    let count: number = 0;\n    for (let i: number = 0; i < this.reviewRecords.length; i++) {\n      if (this.reviewRecords[i].wasCorrect) {\n        count += 1;\n      }\n    }\n    return count;\n  }\n\n  getWrongCount(): number {\n    let count: number = 0;\n    for (let i: number = 0; i < this.reviewRecords.length; i++) {\n      if (!this.reviewRecords[i].wasCorrect) {\n        count += 1;\n      }\n    }\n    return count;\n  }\n\n  getAccuracyRate(): number {\n    const total: number = this.reviewRecords.length;\n    if (total === 0) {\n      return 0;\n    }\n    return Math.round((this.getCorrectCount() / total) * 100);\n  }\n\n  getAveragePerDay(): number {\n    const total: number = this.reviewRecords.length;\n    if (total === 0) {\n      return 0;\n    }\n    const today: string = todayKey();\n    let earliest: string = this.reviewRecords[0].reviewDate;\n    for (let i: number = 1; i < this.reviewRecords.length; i++) {\n      const key: string = recordDateKey(this.reviewRecords[i].reviewDate);\n      if (key.length > 0 && key < earliest) {\n        earliest = key;\n      }\n    }\n    const earliestKey: string = recordDateKey(earliest);\n    if (earliestKey.length === 0) {\n      return total;\n    }\n    const days: number = diffDays(today, earliestKey) + 1;\n    if (days <= 0) {\n      return total;\n    }\n    return Math.round((total / days) * 10) / 10;\n  }\n}\n","src/ets/service/StorageService.ets":"// 持久化存储服务：基于 preferences 的键值存储，JSON 序列化保存学习数据\nimport { preferences } from '@kit.ArkData';\nimport { hilog } from '@kit.PerformanceAnalysisKit';\nimport { common } from '@kit.AbilityKit';\nimport { AppConstants } from '../common/AppConstants';\nimport {\n  CheckInRecord,\n  ReviewRecord,\n  UserSettings,\n  WordBookItem,\n  WordItem,\n  WordProgress,\n  createCheckInRecord,\n  createDefaultSettings,\n  createReviewRecord,\n  createWord,\n  createWordBook,\n  createWordProgress,\n} from '../model/WordModel';\n\nconst LOG_DOMAIN: number = 0x0001;\nconst TAG: string = 'StorageService';\n\n// 单词进度持久化条目，key 格式：bookId/word\nexport interface ProgressEntry {\n  key: string;\n  progress: WordProgress;\n}\n\ninterface RawWord {\n  id: string;\n  word: string;\n  phonetic: string;\n  meaning: string;\n  example: string;\n}\n\ninterface RawBook {\n  id: string;\n  name: string;\n  description: string;\n  isBuiltIn: boolean;\n  words: RawWord[];\n}\n\nexport class StorageService {\n  private static instance: StorageService | null = null;\n  private prefs: preferences.Preferences | null = null;\n\n  static getInstance(): StorageService {\n    if (StorageService.instance === null) {\n      StorageService.instance = new StorageService();\n    }\n    return StorageService.instance;\n  }\n\n  async init(context: common.Context): Promise<void> {\n    try {\n      this.prefs = await preferences.getPreferences(context, AppConstants.STORE_NAME);\n      hilog.info(LOG_DOMAIN, TAG, 'preferences initialized');\n    } catch (err) {\n      hilog.error(LOG_DOMAIN, TAG, 'init failed: %{public}s', JSON.stringify(err));\n      throw new Error('本地存储初始化失败，请重试');\n    }\n  }\n\n  private async readString(key: string): Promise<string> {\n    if (this.prefs === null) {\n      return '';\n    }\n    try {\n      const value: string = await this.prefs.get(key, '') as string;\n      return value;\n    } catch (err) {\n      hilog.error(LOG_DOMAIN, TAG, 'read %{public}s failed: %{public}s', key, JSON.stringify(err));\n      return '';\n    }\n  }\n\n  private async writeString(key: string, value: string): Promise<boolean> {\n    if (this.prefs === null) {\n      hilog.error(LOG_DOMAIN, TAG, 'write failed: prefs is null');\n      return false;\n    }\n    try {\n      await this.prefs.put(key, value);\n      await this.prefs.flush();\n      return true;\n    } catch (err) {\n      hilog.error(LOG_DOMAIN, TAG, 'write %{public}s failed: %{public}s', key, JSON.stringify(err));\n      return false;\n    }\n  }\n\n  async loadSettings(): Promise<UserSettings> {\n    const raw: string = await this.readString(AppConstants.KEY_SETTINGS);\n    if (raw.length === 0) {\n      return createDefaultSettings('');\n    }\n    try {\n      const parsed: UserSettings = JSON.parse(raw) as UserSettings;\n      const settings: UserSettings = {\n        themeMode: typeof parsed.themeMode === 'number' ? parsed.themeMode : 0,\n        fontScale: typeof parsed.fontScale === 'number' ? parsed.fontScale : AppConstants.DEFAULT_FONT_SCALE,\n        dailyTarget: typeof parsed.dailyTarget === 'number' && parsed.dailyTarget > 0\n          ? parsed.dailyTarget : AppConstants.DEFAULT_DAILY_TARGET,\n        currentBookId: typeof parsed.currentBookId === 'string' ? parsed.currentBookId : '',\n      };\n      return settings;\n    } catch (err) {\n      hilog.error(LOG_DOMAIN, TAG, 'loadSettings parse failed: %{public}s', JSON.stringify(err));\n      return createDefaultSettings('');\n    }\n  }\n\n  async saveSettings(settings: UserSettings): Promise<boolean> {\n    return await this.writeString(AppConstants.KEY_SETTINGS, JSON.stringify(settings));\n  }\n\n  async loadCheckIns(): Promise<CheckInRecord[]> {\n    const raw: string = await this.readString(AppConstants.KEY_CHECK_INS);\n    if (raw.length === 0) {\n      return [];\n    }\n    try {\n      const parsed: CheckInRecord[] = JSON.parse(raw) as CheckInRecord[];\n      const records: CheckInRecord[] = [];\n      for (let i: number = 0; i < parsed.length; i++) {\n        const item: CheckInRecord = parsed[i];\n        if (typeof item.dateKey === 'string' && item.dateKey.length > 0) {\n          records.push(createCheckInRecord(item.dateKey,\n            typeof item.streak === 'number' ? item.streak : 0,\n            typeof item.learned === 'number' ? item.learned : 0));\n        }\n      }\n      return records;\n    } catch (err) {\n      hilog.error(LOG_DOMAIN, TAG, 'loadCheckIns parse failed: %{public}s', JSON.stringify(err));\n      return [];\n    }\n  }\n\n  async saveCheckIns(records: CheckInRecord[]): Promise<boolean> {\n    return await this.writeString(AppConstants.KEY_CHECK_INS, JSON.stringify(records));\n  }\n\n  async loadReviewRecords(): Promise<ReviewRecord[]> {\n    const raw: string = await this.readString(AppConstants.KEY_REVIEW_RECORDS);\n    if (raw.length === 0) {\n      return [];\n    }\n    try {\n      const parsed: ReviewRecord[] = JSON.parse(raw) as ReviewRecord[];\n      const records: ReviewRecord[] = [];\n      for (let i: number = 0; i < parsed.length; i++) {\n        const item: ReviewRecord = parsed[i];\n        records.push(createReviewRecord(\n          typeof item.id === 'string' ? item.id : '',\n          typeof item.wordBookId === 'string' ? item.wordBookId : '',\n          typeof item.word === 'string' ? item.word : '',\n          typeof item.meaning === 'string' ? item.meaning : '',\n          item.wasCorrect === true,\n          typeof item.reviewDate === 'string' ? item.reviewDate : '',\n          typeof item.levelBefore === 'number' ? item.levelBefore : 0,\n          typeof item.levelAfter === 'number' ? item.levelAfter : 0,\n        ));\n      }\n      return records;\n    } catch (err) {\n      hilog.error(LOG_DOMAIN, TAG, 'loadReviewRecords parse failed: %{public}s', JSON.stringify(err));\n      return [];\n    }\n  }\n\n  async saveReviewRecords(records: ReviewRecord[]): Promise<boolean> {\n    // 仅保留最近 1000 条，避免无限增长\n    const start: number = records.length > 1000 ? records.length - 1000 : 0;\n    const trimmed: ReviewRecord[] = records.slice(start);\n    return await this.writeString(AppConstants.KEY_REVIEW_RECORDS, JSON.stringify(trimmed));\n  }\n\n  async loadProgressEntries(): Promise<ProgressEntry[]> {\n    const raw: string = await this.readString(AppConstants.KEY_WORD_PROGRESS);\n    if (raw.length === 0) {\n      return [];\n    }\n    try {\n      const parsed: ProgressEntry[] = JSON.parse(raw) as ProgressEntry[];\n      const entries: ProgressEntry[] = [];\n      for (let i: number = 0; i < parsed.length; i++) {\n        const item: ProgressEntry = parsed[i];\n        if (typeof item.key !== 'string' || item.key.length === 0) {\n          continue;\n        }\n        const source: WordProgress = item.progress ? item.progress : createWordProgress();\n        entries.push({\n          key: item.key,\n          progress: {\n            ebbinghausLevel: typeof source.ebbinghausLevel === 'number' ? source.ebbinghausLevel : 0,\n            reviewCount: typeof source.reviewCount === 'number' ? source.reviewCount : 0,\n            mastered: source.mastered === true,\n            lastReviewDate: typeof source.lastReviewDate === 'string' ? source.lastReviewDate : '',\n            nextReviewDate: typeof source.nextReviewDate === 'string' ? source.nextReviewDate : '',\n          },\n        });\n      }\n      return entries;\n    } catch (err) {\n      hilog.error(LOG_DOMAIN, TAG, 'loadProgressEntries parse failed: %{public}s', JSON.stringify(err));\n      return [];\n    }\n  }\n\n  async saveProgressEntries(entries: ProgressEntry[]): Promise<boolean> {\n    return await this.writeString(AppConstants.KEY_WORD_PROGRESS, JSON.stringify(entries));\n  }\n\n  async loadImportedBooks(): Promise<WordBookItem[]> {\n    const raw: string = await this.readString(AppConstants.KEY_IMPORTED_BOOKS);\n    if (raw.length === 0) {\n      return [];\n    }\n    try {\n      const parsed: RawBook[] = JSON.parse(raw) as RawBook[];\n      const books: WordBookItem[] = [];\n      for (let i: number = 0; i < parsed.length; i++) {\n        const rawBook: RawBook = parsed[i];\n        if (typeof rawBook.id !== 'string' || rawBook.id.length === 0) {\n          continue;\n        }\n        const words: WordItem[] = [];\n        if (rawBook.words instanceof Array) {\n          for (let j: number = 0; j < rawBook.words.length; j++) {\n            const rawWord: RawWord = rawBook.words[j];\n            words.push(createWord(\n              typeof rawWord.id === 'string' ? rawWord.id : `${rawBook.id}_${j}`,\n              typeof rawWord.word === 'string' ? rawWord.word : '',\n              typeof rawWord.phonetic === 'string' ? rawWord.phonetic : '',\n              typeof rawWord.meaning === 'string' ? rawWord.meaning : '暂无释义',\n              typeof rawWord.example === 'string' ? rawWord.example : '',\n            ));\n          }\n        }\n        books.push(createWordBook(\n          rawBook.id,\n          typeof rawBook.name === 'string' ? rawBook.name : '导入词书',\n          typeof rawBook.description === 'string' ? rawBook.description : '用户导入词表',\n          false,\n          words,\n        ));\n      }\n      return books;\n    } catch (err) {\n      hilog.error(LOG_DOMAIN, TAG, 'loadImportedBooks parse failed: %{public}s', JSON.stringify(err));\n      return [];\n    }\n  }\n\n  async saveImportedBooks(books: WordBookItem[]): Promise<boolean> {\n    return await this.writeString(AppConstants.KEY_IMPORTED_BOOKS, JSON.stringify(books));\n  }\n\n  async readAchievementData(): Promise<string> {\n    return await this.readString(AppConstants.KEY_ACHIEVEMENTS);\n  }\n\n  async writeAchievementData(data: string): Promise<void> {\n    await this.writeString(AppConstants.KEY_ACHIEVEMENTS, data);\n  }\n\n  async loadQuizCount(): Promise<number> {\n    const raw: string = await this.readString(AppConstants.KEY_QUIZ_COUNT);\n    if (raw.length === 0) {\n      return 0;\n    }\n    const value: number = Number(raw);\n    return isNaN(value) ? 0 : value;\n  }\n\n  async saveQuizCount(count: number): Promise<void> {\n    await this.writeString(AppConstants.KEY_QUIZ_COUNT, String(count));\n  }\n\n  async resetAll(): Promise<boolean> {\n    if (this.prefs === null) {\n      return false;\n    }\n    try {\n      await this.prefs.clear();\n      await this.prefs.flush();\n      hilog.info(LOG_DOMAIN, TAG, 'all data reset');\n      return true;\n    } catch (err) {\n      hilog.error(LOG_DOMAIN, TAG, 'resetAll failed: %{public}s', JSON.stringify(err));\n      return false;\n    }\n  }\n}\n","src/ets/service/TtsService.ets":"// TTS 语音服务：基于 CoreSpeechKit 朗读英文单词，失败全程静默降级\nimport { textToSpeech } from '@kit.CoreSpeechKit';\nimport { BusinessError } from '@kit.BasicServicesKit';\nimport { hilog } from '@kit.PerformanceAnalysisKit';\n\nconst LOG_DOMAIN: number = 0x0005;\nconst TAG: string = 'TtsService';\n\nexport class TtsService {\n  private static instance: TtsService | null = null;\n  private engine: textToSpeech.TextToSpeechEngine | null = null;\n  private ready: boolean = false;\n\n  static getInstance(): TtsService {\n    if (TtsService.instance === null) {\n      TtsService.instance = new TtsService();\n    }\n    return TtsService.instance;\n  }\n\n  async init(): Promise<void> {\n    if (this.ready || this.engine !== null) {\n      return;\n    }\n    // 先查询设备支持的音色列表，英文 en-US 对应 person: 8\n    let availablePerson: number = 8;\n    let voiceInstalled: boolean = false;\n    try {\n      const query: textToSpeech.VoiceQuery = {\n        requestId: `voice_${Date.now()}`,\n        online: 1,\n      };\n      const voices: textToSpeech.VoiceInfo[] = await textToSpeech.listVoices(query);\n      for (let i: number = 0; i < voices.length; i++) {\n        if (voices[i].language.indexOf('en') >= 0) {\n          availablePerson = voices[i].person;\n          voiceInstalled = voices[i].status === 'INSTALLED';\n          break;\n        }\n      }\n      hilog.info(LOG_DOMAIN, TAG, 'listVoices: %{public}d voices, en person=%{public}d installed=%{public}s',\n        voices.length, availablePerson, String(voiceInstalled));\n    } catch (err) {\n      hilog.warn(LOG_DOMAIN, TAG, 'listVoices failed, use default person 8: %{public}s', JSON.stringify(err));\n    }\n\n    // 若英文音色未安装，先下载\n    if (!voiceInstalled) {\n      try {\n        await this.downloadVoice(availablePerson);\n        hilog.info(LOG_DOMAIN, TAG, 'voice download completed');\n      } catch (err) {\n        hilog.warn(LOG_DOMAIN, TAG, 'voice download failed, try createEngine anyway: %{public}s', JSON.stringify(err));\n      }\n    }\n\n    // 多种参数组合降级尝试，兼容不同设备的 HiAI TTS 服务\n    const strategies: textToSpeech.CreateEngineParams[] = [];\n    const extra1: Record<string, Object> = {};\n    extra1.style = 'interaction-broadcast';\n    extra1.locate = 'CN';\n    extra1.name = 'WordAppEngine';\n    // 策略1：官方推荐参数，person 用英文音色\n    strategies.push({\n      language: 'en-US',\n      person: availablePerson,\n      online: 1,\n      extraParams: extra1,\n    });\n    // 策略2：无 extraParams\n    strategies.push({ language: 'en-US', person: availablePerson, online: 1 } as textToSpeech.CreateEngineParams);\n    // 策略3：仅 person + language\n    strategies.push({ language: 'en-US', person: availablePerson } as textToSpeech.CreateEngineParams);\n\n    for (let i: number = 0; i < strategies.length; i++) {\n      try {\n        const engine: textToSpeech.TextToSpeechEngine = await textToSpeech.createEngine(strategies[i]);\n        const listener: textToSpeech.SpeakListener = {\n          onStart: (requestId: string, response: textToSpeech.StartResponse): void => {\n          },\n          onComplete: (requestId: string, response: textToSpeech.CompleteResponse): void => {\n          },\n          onStop: (requestId: string, response: textToSpeech.StopResponse): void => {\n          },\n          onError: (requestId: string, errorCode: number, errorMessage: string): void => {\n            hilog.error(LOG_DOMAIN, TAG,\n              'tts speak error: %{public}s %{public}d %{public}s', requestId, errorCode, errorMessage);\n          },\n        };\n        engine.setListener(listener);\n        this.engine = engine;\n        this.ready = true;\n        hilog.info(LOG_DOMAIN, TAG, 'tts engine ready (strategy %{public}d)', i + 1);\n        return;\n      } catch (err) {\n        hilog.warn(LOG_DOMAIN, TAG, 'tts init strategy %{public}d failed: %{public}s',\n          i + 1, JSON.stringify(err));\n      }\n    }\n    this.ready = false;\n    hilog.error(LOG_DOMAIN, TAG, 'tts init failed: all strategies exhausted');\n  }\n\n  private downloadVoice(person: number): Promise<void> {\n    return new Promise<void>((resolve: () => void, reject: (err: Error) => void) => {\n      const downloadParams: textToSpeech.VoiceDownload = {\n        requestId: `dl_${Date.now()}`,\n        language: 'en-US',\n        person: person,\n        style: 'interaction-broadcast',\n      };\n      textToSpeech.downloadVoice(downloadParams, (err: BusinessError | undefined, response: textToSpeech.DownloadResponse) => {\n        if (err) {\n          // 1002300010 = 音色已下载，视为成功\n          if (err.code === 1002300010) {\n            resolve();\n          } else {\n            reject(new Error(`downloadVoice failed: ${err.code} ${err.message}`));\n          }\n        } else {\n          hilog.info(LOG_DOMAIN, TAG, 'downloadVoice response: %{public}s', JSON.stringify(response));\n          resolve();\n        }\n      });\n    });\n  }\n\n  async speak(text: string): Promise<void> {\n    const engine: textToSpeech.TextToSpeechEngine | null = this.engine;\n    if (!this.ready || engine === null || text.trim().length === 0) {\n      return;\n    }\n    try {\n      const speakParam: textToSpeech.SpeakParams = {\n        requestId: `utter_${Date.now()}`,\n      };\n      await engine.speak(text.trim(), speakParam);\n    } catch (err) {\n      hilog.error(LOG_DOMAIN, TAG, 'tts speak failed: %{public}s', JSON.stringify(err));\n    }\n  }\n\n  shutdown(): void {\n    const engine: textToSpeech.TextToSpeechEngine | null = this.engine;\n    try {\n      if (engine !== null) {\n        engine.shutdown();\n      }\n    } catch (err) {\n      hilog.error(LOG_DOMAIN, TAG, 'tts shutdown failed: %{public}s', JSON.stringify(err));\n    }\n    this.engine = null;\n    this.ready = false;\n  }\n}\n","src/ets/service/WordBookService.ets":"// 词书服务：从 rawfile 加载内置词书、管理用户导入词书\nimport { common } from '@kit.AbilityKit';\nimport { util } from '@kit.ArkTS';\nimport { hilog } from '@kit.PerformanceAnalysisKit';\nimport { AppConstants } from '../common/AppConstants';\nimport {\n  BuiltInBookDef,\n  WordBookItem,\n  WordItem,\n  createWord,\n  createWordBook,\n} from '../model/WordModel';\nimport { StorageService } from './StorageService';\n\nconst LOG_DOMAIN: number = 0x0002;\nconst TAG: string = 'WordBookService';\n\ninterface RawWord {\n  id: string;\n  word: string;\n  phonetic: string;\n  meaning: string;\n  example: string;\n}\n\nexport interface ImportedBookData {\n  id: string;\n  name: string;\n  description: string;\n  words: WordItem[];\n}\n\nfunction dedupeWords(words: WordItem[]): WordItem[] {\n  const result: WordItem[] = [];\n  const seen: string[] = [];\n  for (let i: number = 0; i < words.length; i++) {\n    const item: WordItem = words[i];\n    const key: string = item.word.trim().toLowerCase();\n    if (key.length === 0 || seen.indexOf(key) >= 0) {\n      continue;\n    }\n    seen.push(key);\n    result.push(item);\n  }\n  return result;\n}\n\nexport class WordBookService {\n  private static instance: WordBookService | null = null;\n  private books: WordBookItem[] = [];\n\n  static getInstance(): WordBookService {\n    if (WordBookService.instance === null) {\n      WordBookService.instance = new WordBookService();\n    }\n    return WordBookService.instance;\n  }\n\n  async init(context: common.Context): Promise<void> {\n    const loaded: WordBookItem[] = [];\n    for (let i: number = 0; i < AppConstants.BUILT_IN_BOOKS.length; i++) {\n      const def: BuiltInBookDef = AppConstants.BUILT_IN_BOOKS[i];\n      const book: WordBookItem = await this.loadBuiltInBook(context, def);\n      loaded.push(book);\n    }\n    const imported: WordBookItem[] = await StorageService.getInstance().loadImportedBooks();\n    for (let i: number = 0; i < imported.length; i++) {\n      loaded.push(imported[i]);\n    }\n    this.books = loaded;\n    hilog.info(LOG_DOMAIN, TAG, 'books loaded: %{public}d', this.books.length);\n  }\n\n  private async loadBuiltInBook(context: common.Context, def: BuiltInBookDef): Promise<WordBookItem> {\n    try {\n      const buffer: Uint8Array = await context.resourceManager.getRawFileContent(def.rawFile);\n      const decoder: util.TextDecoder = util.TextDecoder.create('utf-8');\n      const text: string = decoder.decodeToString(buffer);\n      const words: WordItem[] = this.parseWordArray(text, def.id);\n      return createWordBook(def.id, def.name, def.description, true, words);\n    } catch (err) {\n      hilog.error(LOG_DOMAIN, TAG, 'load %{public}s failed: %{public}s', def.id, JSON.stringify(err));\n      throw new Error(`词书「${def.name}」加载失败，请重启应用重试`);\n    }\n  }\n\n  private parseWordArray(text: string, bookId: string): WordItem[] {\n    const parsed: RawWord[] = JSON.parse(text) as RawWord[];\n    if (!(parsed instanceof Array)) {\n      throw new Error('词库格式错误');\n    }\n    const words: WordItem[] = [];\n    for (let i: number = 0; i < parsed.length; i++) {\n      const item: RawWord = parsed[i];\n      const wordText: string = typeof item.word === 'string' ? item.word.trim() : '';\n      if (wordText.length === 0) {\n        continue;\n      }\n      words.push(createWord(\n        typeof item.id === 'string' && item.id.length > 0 ? item.id : `${bookId}_${i}`,\n        wordText,\n        typeof item.phonetic === 'string' ? item.phonetic : '',\n        typeof item.meaning === 'string' ? item.meaning : '暂无释义',\n        typeof item.example === 'string' ? item.example : '',\n      ));\n    }\n    return words;\n  }\n\n  getAllBooks(): WordBookItem[] {\n    return this.books;\n  }\n\n  getBook(bookId: string): WordBookItem | undefined {\n    for (let i: number = 0; i < this.books.length; i++) {\n      if (this.books[i].id === bookId) {\n        return this.books[i];\n      }\n    }\n    return undefined;\n  }\n\n  getBookWords(bookId: string): WordItem[] {\n    const book: WordBookItem | undefined = this.getBook(bookId);\n    return book ? book.words : [];\n  }\n\n  // 每日一词：根据日期键确定性地从当前词书选取一个单词\n  getDailyWord(bookId: string, dateKey: string): WordItem | undefined {\n    const words: WordItem[] = this.getBookWords(bookId);\n    if (words.length === 0) {\n      return undefined;\n    }\n    let hash: number = 0;\n    for (let i: number = 0; i < dateKey.length; i++) {\n      hash = (hash * 31 + dateKey.charCodeAt(i)) % 2147483647;\n    }\n    const index: number = hash >= 0 ? hash % words.length : (-hash) % words.length;\n    return words[index];\n  }\n\n  sanitizeBookId(value: string): string {\n    const trimmed: string = value.trim();\n    if (trimmed.length === 0) {\n      return `import_${Date.now()}`;\n    }\n    return trimmed.replace(/\\s+/g, '_');\n  }\n\n  // TXT 格式：每行 word-meaning-phonetic-example（分隔符 - | , ； ;）\n  parseImportedText(raw: string, id: string, name: string, description: string): ImportedBookData {\n    const lines: string[] = raw.split(/\\r?\\n/);\n    const words: WordItem[] = [];\n    for (let i: number = 0; i < lines.length; i++) {\n      const line: string = lines[i].trim();\n      if (line.length === 0) {\n        continue;\n      }\n      const parts: string[] = line.split(/\\s*[-|,；;]\\s*/);\n      const wordText: string = parts.length > 0 ? parts[0].trim() : '';\n      if (wordText.length === 0) {\n        continue;\n      }\n      const meaning: string = parts.length > 1 && parts[1].trim().length > 0 ? parts[1].trim() : '暂无释义';\n      const phonetic: string = parts.length > 2 ? parts[2].trim() : '';\n      const example: string = parts.length > 3 && parts[3].trim().length > 0\n        ? parts[3].trim() : `Example for ${wordText}.`;\n      words.push(createWord(`${id}_${i}`, wordText, phonetic, meaning, example));\n    }\n    const data: ImportedBookData = {\n      id: id,\n      name: name,\n      description: description,\n      words: dedupeWords(words),\n    };\n    return data;\n  }\n\n  parseImportedJson(raw: string, id: string, name: string, description: string): ImportedBookData {\n    const parsed: RawWord[] = JSON.parse(raw) as RawWord[];\n    if (!(parsed instanceof Array)) {\n      throw new Error('JSON 格式应为单词数组');\n    }\n    const words: WordItem[] = [];\n    for (let i: number = 0; i < parsed.length; i++) {\n      const item: RawWord = parsed[i];\n      const wordText: string = typeof item.word === 'string' ? item.word.trim() : '';\n      if (wordText.length === 0) {\n        continue;\n      }\n      words.push(createWord(\n        typeof item.id === 'string' && item.id.length > 0 ? item.id : `${id}_${i}`,\n        wordText,\n        typeof item.phonetic === 'string' ? item.phonetic : '',\n        typeof item.meaning === 'string' && item.meaning.trim().length > 0 ? item.meaning : '暂无释义',\n        typeof item.example === 'string' && item.example.trim().length > 0\n          ? item.example : `Example for ${wordText}.`,\n      ));\n    }\n    const data: ImportedBookData = {\n      id: id,\n      name: name,\n      description: description,\n      words: dedupeWords(words),\n    };\n    return data;\n  }\n\n  // 导入词书：同名 id 覆盖，持久化到 preferences\n  async addImportedBook(data: ImportedBookData): Promise<WordBookItem> {\n    const book: WordBookItem = createWordBook(data.id, data.name, data.description, false, data.words);\n    const nextBooks: WordBookItem[] = [];\n    let replaced: boolean = false;\n    for (let i: number = 0; i < this.books.length; i++) {\n      if (this.books[i].id === book.id && !this.books[i].isBuiltIn) {\n        nextBooks.push(book);\n        replaced = true;\n      } else {\n        nextBooks.push(this.books[i]);\n      }\n    }\n    if (!replaced) {\n      nextBooks.push(book);\n    }\n    const importedOnly: WordBookItem[] = [];\n    for (let i: number = 0; i < nextBooks.length; i++) {\n      if (!nextBooks[i].isBuiltIn) {\n        importedOnly.push(nextBooks[i]);\n      }\n    }\n    const saved: boolean = await StorageService.getInstance().saveImportedBooks(importedOnly);\n    if (!saved) {\n      throw new Error('词书保存失败，请检查存储空间后重试');\n    }\n    this.books = nextBooks;\n    return book;\n  }\n}\n","src/ets/view/HomePage.ets":"// 首页：学习指标、今日任务、每日一词、词书切换、签到\nimport { AppTheme } from '../common/AppTheme';\nimport { todayKey } from '../common/DateUtils';\nimport { BookItemCard } from '../widget/BookItemCard';\nimport { CheckInButton } from '../widget/CheckInButton';\nimport { StatCard } from '../widget/StatCard';\nimport { WordBookItem, WordItem, createWord } from '../model/WordModel';\nimport { CheckInService } from '../service/CheckInService';\nimport { ReviewSchedulerService } from '../service/ReviewSchedulerService';\nimport { TtsService } from '../service/TtsService';\nimport { WordBookService } from '../service/WordBookService';\n\ninterface BookViewData {\n  id: string;\n  name: string;\n  description: string;\n  wordCount: number;\n  masteredCount: number;\n}\n\n@Component\nexport struct HomePage {\n  @Prop fontScale: number = 1.0;\n  @Prop currentBookId: string = '';\n  @Prop dailyTarget: number = 20;\n  @Prop @Watch('onRefreshTick') refreshTick: number = 0;\n  onSwitchBook: (bookId: string) => void = (bookId: string) => {};\n  onGoStudy: () => void = () => {};\n  onGoQuiz: () => void = () => {};\n  onDataChanged: () => void = () => {};\n\n  @State books: BookViewData[] = [];\n  @State checkedIn: boolean = false;\n  @State streak: number = 0;\n  @State todayLearned: number = 0;\n  @State masteredCount: number = 0;\n  @State dueCount: number = 0;\n  @State newWordCount: number = 0;\n  @State learningCount: number = 0;\n  @State currentBookWordCount: number = 0;\n  @State dailyWord: WordItem = createWord('', '', '', '', '');\n\n  aboutToAppear(): void {\n    this.loadData();\n  }\n\n  onRefreshTick(): void {\n    this.loadData();\n  }\n\n  private loadData(): void {\n    const scheduler: ReviewSchedulerService = ReviewSchedulerService.getInstance();\n    const allBooks: WordBookItem[] = WordBookService.getInstance().getAllBooks();\n    const viewData: BookViewData[] = [];\n    for (let i: number = 0; i < allBooks.length; i++) {\n      const item: BookViewData = {\n        id: allBooks[i].id,\n        name: allBooks[i].name,\n        description: allBooks[i].description,\n        wordCount: allBooks[i].words.length,\n        masteredCount: scheduler.getMasteredCount(allBooks[i].id),\n      };\n      viewData.push(item);\n    }\n    this.books = viewData;\n    this.checkedIn = CheckInService.getInstance().hasCheckedInToday();\n    this.streak = CheckInService.getInstance().getCurrentStreak();\n    this.todayLearned = scheduler.getTodayLearnedCount();\n    this.masteredCount = scheduler.getMasteredCount(this.currentBookId);\n    this.dueCount = scheduler.getDueCount(this.currentBookId);\n    this.newWordCount = scheduler.getNewWordCount(this.currentBookId);\n    this.learningCount = scheduler.getLearningCount(this.currentBookId) + this.masteredCount;\n    this.currentBookWordCount = 0;\n    for (let i: number = 0; i < viewData.length; i++) {\n      if (viewData[i].id === this.currentBookId) {\n        this.currentBookWordCount = viewData[i].wordCount;\n        break;\n      }\n    }\n    const daily: WordItem | undefined = WordBookService.getInstance().getDailyWord(this.currentBookId, todayKey());\n    this.dailyWord = daily !== undefined ? daily : createWord('', '', '', '暂无单词', '');\n    // 今日已签到时，把最新学习量回写签到记录快照（保存内部已吞异常）\n    if (this.checkedIn) {\n      CheckInService.getInstance().updateTodayLearned(this.todayLearned);\n    }\n  }\n\n  private async doCheckIn(): Promise<void> {\n    const learned: number = ReviewSchedulerService.getInstance().getTodayLearnedCount();\n    const ok: boolean = await CheckInService.getInstance().checkIn(learned);\n    if (ok) {\n      this.loadData();\n      this.onDataChanged();\n    }\n  }\n\n  private dailyProgress(): number {\n    return this.dailyTarget <= 0 ? 0 : Math.min(this.todayLearned / this.dailyTarget, 1);\n  }\n\n  build() {\n    Column() {\n      Stack() {\n        Column()\n          .width(96)\n          .height(96)\n          .borderRadius(999)\n          .backgroundColor($r('app.color.color_chip_background'))\n          .position({ x: -28, y: -30 })\n          .hitTestBehavior(HitTestMode.None)\n        Column()\n          .width(64)\n          .height(64)\n          .borderRadius(999)\n          .backgroundColor($r('app.color.color_chip_background'))\n          .position({ x: 220, y: 86 })\n          .hitTestBehavior(HitTestMode.None)\n\n        Row() {\n          Column() {\n            Text('✦ 每日进步一点点')\n              .fontSize(11 * this.fontScale)\n              .fontColor($r('app.color.text_on_color'))\n              .padding({ left: 10, right: 10, top: 4, bottom: 4 })\n              .borderRadius(999)\n              .backgroundColor($r('app.color.color_chip_background'))\n            Text('离线背单词')\n              .fontSize(24 * this.fontScale)\n              .fontWeight(FontWeight.Bold)\n              .fontColor($r('app.color.text_on_color'))\n              .margin({ top: 10 })\n            Text('艾宾浩斯复习 · 签到打卡 · 完全离线')\n              .fontSize(12 * this.fontScale)\n              .fontColor($r('app.color.text_on_color_muted'))\n              .margin({ top: 5 })\n          }\n          .layoutWeight(1)\n          .alignItems(HorizontalAlign.Start)\n\n          Column() {\n            Image($r('app.media.mascot_owl'))\n              .width(68)\n              .height(68)\n          }\n          .width(82)\n          .height(82)\n          .borderRadius(999)\n          .backgroundColor($r('app.color.color_chip_background'))\n          .justifyContent(FlexAlign.Center)\n        }\n        .width('100%')\n      }\n      .width('100%')\n      .padding(18)\n      .borderRadius(22)\n      .linearGradient(AppTheme.primaryGradient())\n      .clip(true)\n      .margin({ bottom: 14 })\n\n      Row() {\n        StatCard({\n          title: '今日学习',\n          value: `${this.todayLearned}`,\n          hint: `计划 ${this.dailyTarget} 词`,\n          accent: 'primary',\n          showProgress: true,\n          progress: this.dailyProgress(),\n          fontScale: this.fontScale,\n        })\n        StatCard({\n          title: '连续签到',\n          value: `${this.streak}`,\n          hint: this.checkedIn ? '今日已签到' : '今日未签到',\n          accent: 'success',\n          showProgress: true,\n          progress: Math.min(this.streak / 30, 1),\n          fontScale: this.fontScale,\n        })\n        StatCard({\n          title: '已学习',\n          value: `${this.learningCount}`,\n          hint: '当前词书学习进度',\n          accent: 'warning',\n          showProgress: true,\n          progress: this.books.length > 0 && this.currentBookWordCount > 0\n            ? Math.min(this.learningCount / this.currentBookWordCount, 1) : 0,\n          fontScale: this.fontScale,\n        })\n      }\n      .width('100%')\n      .justifyContent(FlexAlign.SpaceBetween)\n      .margin({ bottom: 12 })\n\n      if (this.dailyWord.word.length > 0) {\n        Row() {\n          Column() {\n            Row() {\n              Text('每日一词')\n                .fontSize(11 * this.fontScale)\n                .fontColor($r('app.color.text_on_color'))\n                .padding({ left: 8, right: 8, top: 3, bottom: 3 })\n                .borderRadius(999)\n                .backgroundColor($r('app.color.color_chip_background'))\n              Text(this.dailyWord.word)\n                .fontSize(20 * this.fontScale)\n                .fontWeight(FontWeight.Bold)\n                .fontColor($r('app.color.text_on_color'))\n                .margin({ left: 8 })\n                .layoutWeight(1)\n              Button('朗读')\n                .fontSize(11 * this.fontScale)\n                .height(28)\n                .padding({ left: 10, right: 10 })\n                .backgroundColor($r('app.color.color_chip_background'))\n                .fontColor($r('app.color.text_on_color'))\n                .onClick(() => {\n                  TtsService.getInstance().speak(this.dailyWord.word);\n                })\n            }\n            .width('100%')\n            Text(this.dailyWord.meaning)\n              .fontSize(13 * this.fontScale)\n              .fontColor($r('app.color.text_on_color_muted'))\n              .margin({ top: 6 })\n              .width('100%')\n          }\n          .layoutWeight(1)\n          .alignItems(HorizontalAlign.Start)\n        }\n        .width('100%')\n        .padding(14)\n        .borderRadius(AppTheme.CARD_RADIUS)\n        .linearGradient(AppTheme.primaryGradient())\n        .clip(true)\n        .margin({ bottom: 12 })\n      }\n\n      Column() {\n        Row() {\n          Row({ space: 8 }) {\n            Column() {\n              Text('复')\n                .fontSize(14 * this.fontScale)\n                .fontWeight(FontWeight.Bold)\n                .fontColor($r('app.color.danger'))\n            }\n            .width(34)\n            .height(34)\n            .borderRadius(12)\n            .backgroundColor($r('app.color.danger_container'))\n            .justifyContent(FlexAlign.Center)\n\n            Column() {\n              Text('今日待复习')\n                .fontSize(12 * this.fontScale)\n                .fontColor($r('app.color.text_secondary'))\n              Text(`${this.dueCount}`)\n                .fontSize(22 * this.fontScale)\n                .fontWeight(FontWeight.Bold)\n                .fontColor($r('app.color.danger'))\n                .margin({ top: 2 })\n            }\n            .alignItems(HorizontalAlign.Start)\n          }\n          .layoutWeight(1)\n\n          Row({ space: 8 }) {\n            Column() {\n              Text('新')\n                .fontSize(14 * this.fontScale)\n                .fontWeight(FontWeight.Bold)\n                .fontColor($r('app.color.accent_teal'))\n            }\n            .width(34)\n            .height(34)\n            .borderRadius(12)\n            .backgroundColor($r('app.color.accent_teal_container'))\n            .justifyContent(FlexAlign.Center)\n\n            Column() {\n              Text('待学新词')\n                .fontSize(12 * this.fontScale)\n                .fontColor($r('app.color.text_secondary'))\n              Text(`${this.newWordCount}`)\n                .fontSize(22 * this.fontScale)\n                .fontWeight(FontWeight.Bold)\n                .fontColor($r('app.color.accent_teal'))\n                .margin({ top: 2 })\n            }\n            .alignItems(HorizontalAlign.Start)\n          }\n          .layoutWeight(1)\n\n          Button('开始背词')\n            .height(40)\n            .fontSize(14 * this.fontScale)\n            .backgroundColor($r('app.color.primary'))\n            .fontColor($r('app.color.on_primary'))\n            .onClick(() => {\n              this.onGoStudy();\n            })\n        }\n        .width('100%')\n      }\n      .width('100%')\n      .padding(16)\n      .borderRadius(AppTheme.CARD_RADIUS)\n      .backgroundColor($r('app.color.card_background'))\n      .shadow(AppTheme.cardShadow())\n      .margin({ bottom: 14 })\n\n      Row({ space: 8 }) {\n        Column()\n          .width(4)\n          .height(16)\n          .borderRadius(999)\n          .backgroundColor($r('app.color.accent_purple'))\n        Text('词书切换')\n          .fontSize(16 * this.fontScale)\n          .fontWeight(FontWeight.Bold)\n          .fontColor($r('app.color.text_main'))\n      }\n      .width('100%')\n      .margin({ bottom: 8 })\n\n      List({ space: 0 }) {\n        ForEach(this.books, (book: BookViewData) => {\n          ListItem() {\n            BookItemCard({\n              bookName: book.name,\n              description: book.description,\n              wordCount: book.wordCount,\n              masteredCount: book.masteredCount,\n              isSelected: this.currentBookId === book.id,\n              fontScale: this.fontScale,\n              onSelect: () => {\n                this.onSwitchBook(book.id);\n              },\n            })\n          }\n        }, (book: BookViewData) => book.id)\n      }\n      .layoutWeight(1)\n      .width('100%')\n\n      Row({ space: AppTheme.SPACE_NORMAL }) {\n        CheckInButton({\n          checkedIn: this.checkedIn,\n          fontScale: this.fontScale,\n          onCheckIn: () => {\n            this.doCheckIn();\n          },\n        })\n        Button('背词')\n          .layoutWeight(1)\n          .height(44)\n          .fontSize(15 * this.fontScale)\n          .backgroundColor($r('app.color.accent_teal_container'))\n          .fontColor($r('app.color.accent_teal'))\n          .onClick(() => {\n            this.onGoStudy();\n          })\n        Button('自测')\n          .layoutWeight(1)\n          .height(44)\n          .fontSize(15 * this.fontScale)\n          .backgroundColor($r('app.color.accent_purple_container'))\n          .fontColor($r('app.color.accent_purple'))\n          .onClick(() => {\n            this.onGoQuiz();\n          })\n      }\n      .width('100%')\n      .margin({ top: 12 })\n    }\n    .width('100%')\n    .height('100%')\n    .padding(AppTheme.PAGE_PADDING)\n    .backgroundColor($r('app.color.page_background'))\n  }\n}\n","src/ets/view/QuizPage.ets":"// 自测页：英译汉 / 汉译英 / 默写三模式，4 选项随机打乱，错题回写复习调度\nimport { AppConstants } from '../common/AppConstants';\nimport { AppTheme } from '../common/AppTheme';\nimport { WordItem, createWord } from '../model/WordModel';\nimport {\n  QUIZ_MODE_CN_TO_EN,\n  QUIZ_MODE_DICTATION,\n  QUIZ_MODE_EN_TO_CN,\n  QuizResult,\n  QuizService,\n} from '../service/QuizService';\nimport { ReviewSchedulerService } from '../service/ReviewSchedulerService';\nimport { TtsService } from '../service/TtsService';\nimport { WordBookService } from '../service/WordBookService';\n\ninterface ModeTab {\n  mode: number;\n  label: string;\n}\n\ninterface CountTab {\n  count: number;\n  label: string;\n}\n\n@Component\nexport struct QuizPage {\n  @Prop fontScale: number = 1.0;\n  @Prop @Watch('onBookChanged') currentBookId: string = '';\n  onDataChanged: () => void = () => {};\n\n  // phase: 0 配置 1 答题 2 结果\n  @State phase: number = 0;\n  @State mode: number = QUIZ_MODE_EN_TO_CN;\n  @State quizCount: number = 5;\n  @State options: string[] = [];\n  @State selectedOption: string = '';\n  @State answered: boolean = false;\n  @State lastCorrect: boolean = false;\n  @State correctCount: number = 0;\n  @State wrongCount: number = 0;\n  @State dictationInput: string = '';\n  @State quizError: string = '';\n  @State resultTotal: number = 0;\n  @State resultCorrect: number = 0;\n  @State resultWrong: number = 0;\n  @State resultWrongWords: WordItem[] = [];\n  @State quizProcessing: boolean = false;\n  @State questionIndex: number = 0;\n  @State currentWordState: WordItem = createWord('', '', '', '暂无单词', '');\n\n  private modeTabs: ModeTab[] = [\n    { mode: QUIZ_MODE_EN_TO_CN, label: '英译汉' },\n    { mode: QUIZ_MODE_CN_TO_EN, label: '汉译英' },\n    { mode: QUIZ_MODE_DICTATION, label: '默写' },\n  ];\n  private countTabs: CountTab[] = [\n    { count: 5, label: '5题' },\n    { count: 10, label: '10题' },\n    { count: 20, label: '20题' },\n  ];\n\n  aboutToAppear(): void {\n  }\n\n  onBookChanged(): void {\n    this.phase = 0;\n    this.quizError = '';\n  }\n\n  private modeLabel(): string {\n    if (this.mode === QUIZ_MODE_EN_TO_CN) {\n      return '看词选义';\n    }\n    if (this.mode === QUIZ_MODE_CN_TO_EN) {\n      return '看义选词';\n    }\n    return '默写挑战';\n  }\n\n  private correctAnswer(): string {\n    return this.mode === QUIZ_MODE_EN_TO_CN ? this.currentWordState.meaning : this.currentWordState.word;\n  }\n\n  private dictationHint(): string {\n    const word: string = this.currentWordState.word;\n    if (word.length === 0) {\n      return '';\n    }\n    const firstLetter: string = word.charAt(0);\n    const remaining: number = word.length - 1;\n    let hint: string = firstLetter;\n    for (let i: number = 0; i < remaining; i++) {\n      hint += '_';\n    }\n    return hint;\n  }\n\n  private startQuiz(): void {\n    const totalWords: number = WordBookService.getInstance().getBookWords(this.currentBookId).length;\n    if (this.mode !== QUIZ_MODE_DICTATION && totalWords > 0 && totalWords < AppConstants.QUIZ_OPTION_COUNT) {\n      this.quizError = '选择题需要词书至少 4 个单词，可改用默写模式';\n      return;\n    }\n    QuizService.getInstance().startQuiz(this.currentBookId, this.mode, this.quizCount);\n    if (QuizService.getInstance().getTotal() === 0) {\n      this.quizError = '当前词书暂无单词，请先切换词书';\n      return;\n    }\n    this.quizError = '';\n    this.correctCount = 0;\n    this.wrongCount = 0;\n    this.answered = false;\n    this.selectedOption = '';\n    this.dictationInput = '';\n    this.resultWrongWords = [];\n    this.phase = 1;\n    this.questionIndex = QuizService.getInstance().getIndex();\n    this.syncQuestion();\n  }\n\n  private syncQuestion(): void {\n    this.questionIndex = QuizService.getInstance().getIndex();\n    const word: WordItem | undefined = QuizService.getInstance().getCurrentWord();\n    if (word !== undefined) {\n      this.currentWordState = word;\n      if (this.mode === QUIZ_MODE_DICTATION) {\n        this.options = [];\n      } else {\n        this.options = QuizService.getInstance().getOptions(this.currentBookId);\n      }\n    }\n  }\n\n  private selectOption(option: string): void {\n    if (this.answered) {\n      return;\n    }\n    this.answered = true;\n    this.selectedOption = option;\n    const correct: boolean = QuizService.getInstance().checkAnswer(option);\n    this.lastCorrect = correct;\n    if (correct) {\n      this.correctCount += 1;\n    } else {\n      this.wrongCount += 1;\n    }\n  }\n\n  private submitDictation(): void {\n    if (this.answered || this.dictationInput.trim().length === 0) {\n      return;\n    }\n    this.answered = true;\n    const correct: boolean = QuizService.getInstance().checkAnswer(this.dictationInput);\n    this.lastCorrect = correct;\n    if (correct) {\n      this.correctCount += 1;\n    } else {\n      this.wrongCount += 1;\n    }\n  }\n\n  private async processWrongWords(): Promise<void> {\n    const wrongWords: WordItem[] = QuizService.getInstance().getResult().wrongWords;\n    for (let i: number = 0; i < wrongWords.length; i++) {\n      await ReviewSchedulerService.getInstance().processReview(this.currentBookId, wrongWords[i], false);\n    }\n  }\n\n  private async nextQuestion(): Promise<void> {\n    // 重入守卫：错题回写 await 期间禁止连点，防止错题重复 processReview 导致记录虚增\n    if (this.quizProcessing) {\n      return;\n    }\n    this.quizProcessing = true;\n    try {\n      QuizService.getInstance().next();\n      if (QuizService.getInstance().isFinished()) {\n        await this.processWrongWords();\n        await QuizService.getInstance().incrementQuizCount();\n        const result: QuizResult = QuizService.getInstance().getResult();\n        this.resultTotal = result.total;\n        this.resultCorrect = result.correct;\n        this.resultWrong = result.wrong;\n        this.resultWrongWords = result.wrongWords;\n        this.phase = 2;\n        this.onDataChanged();\n      } else {\n        this.answered = false;\n        this.selectedOption = '';\n        this.dictationInput = '';\n        this.syncQuestion();\n      }\n    } catch (err) {\n      // 服务层已记录日志并吞掉异常，此处兜底防止未处理 Promise rejection\n    } finally {\n      this.quizProcessing = false;\n    }\n  }\n\n  private backToConfig(): void {\n    this.phase = 0;\n    this.quizError = '';\n    this.questionIndex = 0;\n    this.answered = false;\n    this.selectedOption = '';\n    this.dictationInput = '';\n  }\n\n  private optionBackground(option: string): Resource {\n    if (!this.answered) {\n      return $r('app.color.primary_container');\n    }\n    if (option === this.correctAnswer()) {\n      return $r('app.color.success_container');\n    }\n    if (option === this.selectedOption) {\n      return $r('app.color.danger_container');\n    }\n    return $r('app.color.input_background');\n  }\n\n  private optionFontColor(option: string): Resource {\n    if (!this.answered) {\n      return $r('app.color.primary');\n    }\n    if (option === this.correctAnswer()) {\n      return $r('app.color.success');\n    }\n    if (option === this.selectedOption) {\n      return $r('app.color.danger');\n    }\n    return $r('app.color.text_secondary');\n  }\n\n  private quizProgress(): number {\n    const total: number = QuizService.getInstance().getTotal();\n    if (total <= 0) {\n      return 0;\n    }\n    return Math.min(this.questionIndex / total, 1);\n  }\n\n  private accuracy(): number {\n    if (this.resultTotal === 0) {\n      return 0;\n    }\n    return Math.round((this.resultCorrect / this.resultTotal) * 100);\n  }\n\n  @Builder\n  buildConfig() {\n    Column() {\n      Row() {\n        Column() {\n          Text('自测题库')\n            .fontSize(22 * this.fontScale)\n            .fontWeight(FontWeight.Bold)\n            .fontColor($r('app.color.text_main'))\n          Text('英译汉、汉译英、默写三种模式，答错单词将安排明日复习')\n            .fontSize(13 * this.fontScale)\n            .fontColor($r('app.color.text_secondary'))\n            .margin({ top: 6 })\n        }\n        .layoutWeight(1)\n        .alignItems(HorizontalAlign.Start)\n\n        Column() {\n          Image($r('app.media.mascot_owl'))\n            .width(30)\n            .height(30)\n        }\n        .width(44)\n        .height(44)\n        .borderRadius(999)\n        .backgroundColor($r('app.color.accent_orange_container'))\n        .justifyContent(FlexAlign.Center)\n      }\n      .width('100%')\n      .margin({ bottom: 16 })\n\n      Row({ space: AppTheme.SPACE_SMALL }) {\n        ForEach(this.modeTabs, (tab: ModeTab) => {\n          Button(tab.label)\n            .layoutWeight(1)\n            .height(42)\n            .fontSize(14 * this.fontScale)\n            .backgroundColor(this.mode === tab.mode\n              ? AppTheme.modeAccent(tab.mode) : $r('app.color.card_background'))\n            .fontColor(this.mode === tab.mode ? $r('app.color.on_primary') : $r('app.color.text_main'))\n            .onClick(() => {\n              this.mode = tab.mode;\n              this.quizError = '';\n            })\n        }, (tab: ModeTab) => tab.label)\n      }\n      .width('100%')\n      .margin({ bottom: 12 })\n\n      Row({ space: AppTheme.SPACE_SMALL }) {\n        ForEach(this.countTabs, (tab: CountTab) => {\n          Button(tab.label)\n            .layoutWeight(1)\n            .height(42)\n            .fontSize(14 * this.fontScale)\n            .backgroundColor(this.quizCount === tab.count ? $r('app.color.primary') : $r('app.color.card_background'))\n            .fontColor(this.quizCount === tab.count ? $r('app.color.on_primary') : $r('app.color.text_main'))\n            .onClick(() => {\n              this.quizCount = tab.count;\n            })\n        }, (tab: CountTab) => tab.label)\n      }\n      .width('100%')\n      .margin({ bottom: 20 })\n\n      if (this.quizError.length > 0) {\n        Text(this.quizError)\n          .fontSize(13 * this.fontScale)\n          .fontColor($r('app.color.danger'))\n          .width('100%')\n          .margin({ bottom: 12 })\n      }\n\n      Button('开始自测')\n        .width('100%')\n        .height(48)\n        .fontSize(16 * this.fontScale)\n        .backgroundColor($r('app.color.primary'))\n        .fontColor($r('app.color.on_primary'))\n        .onClick(() => {\n          this.startQuiz();\n        })\n    }\n    .width('100%')\n    .padding(16)\n    .borderRadius(AppTheme.CARD_RADIUS)\n    .backgroundColor($r('app.color.card_background'))\n    .shadow(AppTheme.cardShadow())\n  }\n\n  @Builder\n  buildQuestion() {\n    Column() {\n      Row() {\n        Text(`第 ${this.questionIndex + 1} 题`)\n          .fontSize(13 * this.fontScale)\n          .fontColor($r('app.color.text_secondary'))\n        Text(this.modeLabel())\n          .fontSize(12 * this.fontScale)\n          .fontColor($r('app.color.primary'))\n          .padding({ left: 10, right: 10, top: 6, bottom: 6 })\n          .borderRadius(999)\n          .backgroundColor($r('app.color.primary_container'))\n      }\n      .width('100%')\n      .justifyContent(FlexAlign.SpaceBetween)\n      .margin({ bottom: 12 })\n\n      Column() {\n        Text(this.mode === QUIZ_MODE_EN_TO_CN ? this.currentWordState.word : this.currentWordState.meaning)\n          .fontSize(28 * this.fontScale)\n          .fontWeight(FontWeight.Bold)\n          .fontColor($r('app.color.text_main'))\n          .textAlign(TextAlign.Center)\n        if (this.mode === QUIZ_MODE_EN_TO_CN) {\n          Text(this.currentWordState.phonetic)\n            .fontSize(14 * this.fontScale)\n            .fontColor($r('app.color.text_secondary'))\n            .margin({ top: 6 })\n        }\n        Button('朗读单词')\n          .fontSize(12 * this.fontScale)\n          .height(32)\n          .margin({ top: 10 })\n          .padding({ left: 12, right: 12 })\n          .backgroundColor($r('app.color.primary_container'))\n          .fontColor($r('app.color.primary'))\n          .onClick(() => {\n            TtsService.getInstance().speak(this.currentWordState.word);\n          })\n      }\n      .width('100%')\n      .padding(16)\n      .borderRadius(16)\n      .backgroundColor($r('app.color.input_background'))\n      .margin({ bottom: 14 })\n\n      if (this.mode === QUIZ_MODE_DICTATION) {\n        Row() {\n          Text('字母提示')\n            .fontSize(12 * this.fontScale)\n            .fontColor($r('app.color.text_muted'))\n          Text(this.dictationHint())\n            .fontSize(20 * this.fontScale)\n            .fontWeight(FontWeight.Bold)\n            .fontColor($r('app.color.primary'))\n            .margin({ left: 8 })\n            .letterSpacing(2)\n        }\n        .width('100%')\n        .margin({ bottom: 10 })\n\n        TextInput({ placeholder: '请输入英文单词，忽略大小写', text: this.dictationInput })\n          .width('100%')\n          .height(48)\n          .fontSize(16 * this.fontScale)\n          .backgroundColor($r('app.color.input_background'))\n          .fontColor($r('app.color.text_main'))\n          .placeholderColor($r('app.color.text_muted'))\n          .borderRadius(AppTheme.BUTTON_RADIUS)\n          .enabled(!this.answered)\n          .onChange((value: string) => {\n            this.dictationInput = value;\n          })\n        if (!this.answered) {\n          Button('提交答案')\n            .width('100%')\n            .height(46)\n            .margin({ top: 12 })\n            .fontSize(15 * this.fontScale)\n            .backgroundColor($r('app.color.primary'))\n            .fontColor($r('app.color.on_primary'))\n            .onClick(() => {\n              this.submitDictation();\n            })\n        }\n      } else {\n        Column({ space: 10 }) {\n          ForEach(this.options, (option: string, optionIndex: number) => {\n            Button() {\n              Text(`${String.fromCharCode(65 + optionIndex)}. ${option}`)\n                .width('100%')\n                .fontSize(15 * this.fontScale)\n                .fontColor(this.optionFontColor(option))\n                .textAlign(TextAlign.Start)\n            }\n              .width('100%')\n              .height(48)\n              .padding({ left: 16, right: 16 })\n              .backgroundColor(this.optionBackground(option))\n              .borderRadius(AppTheme.BUTTON_RADIUS)\n              .onClick(() => {\n                this.selectOption(option);\n              })\n          }, (option: string, optionIndex: number) => `${optionIndex}_${option}`)\n        }\n        .width('100%')\n      }\n\n      if (this.answered) {\n        Row() {\n          Text(this.lastCorrect ? '回答正确' : `回答错误，正确答案：${this.correctAnswer()}`)\n            .fontSize(14 * this.fontScale)\n            .fontColor(this.lastCorrect ? $r('app.color.success') : $r('app.color.danger'))\n            .layoutWeight(1)\n          Button(QuizService.getInstance().isLastQuestion() ? '查看结果' : '下一题')\n            .height(40)\n            .fontSize(14 * this.fontScale)\n            .backgroundColor($r('app.color.primary'))\n            .fontColor($r('app.color.on_primary'))\n            .enabled(!this.quizProcessing)\n            .onClick(() => {\n              this.nextQuestion();\n            })\n        }\n        .width('100%')\n        .margin({ top: 14 })\n      }\n    }\n    .width('100%')\n    .padding(16)\n    .borderRadius(AppTheme.CARD_RADIUS)\n    .backgroundColor($r('app.color.card_background'))\n    .shadow(AppTheme.cardShadow())\n  }\n\n  @Builder\n  buildResult() {\n    Stack() {\n      Column()\n        .width(70)\n        .height(70)\n        .borderRadius(999)\n        .backgroundColor($r('app.color.warning_container'))\n        .opacity(0.18)\n        .position({ x: -20, y: -22 })\n        .hitTestBehavior(HitTestMode.None)\n      Column()\n        .width(48)\n        .height(48)\n        .borderRadius(999)\n        .backgroundColor($r('app.color.accent_purple_container'))\n        .opacity(0.18)\n        .position({ x: 286, y: 128 })\n        .hitTestBehavior(HitTestMode.None)\n\n      Column() {\n        Column() {\n          Image($r('app.media.mascot_trophy'))\n            .width(56)\n            .height(56)\n        }\n        .width(84)\n        .height(84)\n        .borderRadius(999)\n        .backgroundColor($r('app.color.warning_container'))\n        .justifyContent(FlexAlign.Center)\n\n        Text('自测完成')\n          .fontSize(24 * this.fontScale)\n          .fontWeight(FontWeight.Bold)\n          .fontColor($r('app.color.text_main'))\n          .margin({ top: 14 })\n      Text(`正确率 ${this.accuracy()}%`)\n        .fontSize(18 * this.fontScale)\n        .fontColor($r('app.color.primary'))\n        .margin({ top: 8 })\n      Row() {\n        Text(`正确 ${this.resultCorrect} 题`)\n          .fontSize(14 * this.fontScale)\n          .fontColor($r('app.color.success'))\n          .layoutWeight(1)\n        Text(`错误 ${this.resultWrong} 题`)\n          .fontSize(14 * this.fontScale)\n          .fontColor($r('app.color.danger'))\n          .layoutWeight(1)\n      }\n      .width('100%')\n      .margin({ top: 12 })\n\n      if (this.resultWrongWords.length > 0) {\n        Text('错题回顾（已安排明日复习）')\n          .fontSize(14 * this.fontScale)\n          .fontWeight(FontWeight.Bold)\n          .fontColor($r('app.color.text_main'))\n          .width('100%')\n          .margin({ top: 16, bottom: 8 })\n        List({ space: 8 }) {\n          ForEach(this.resultWrongWords, (word: WordItem) => {\n            ListItem() {\n              Row() {\n                Text(word.word)\n                  .fontSize(15 * this.fontScale)\n                  .fontColor($r('app.color.danger'))\n                  .fontWeight(FontWeight.Bold)\n                  .layoutWeight(1)\n                Text(word.meaning)\n                  .fontSize(13 * this.fontScale)\n                  .fontColor($r('app.color.text_secondary'))\n              }\n              .width('100%')\n              .padding(12)\n              .borderRadius(12)\n              .backgroundColor($r('app.color.danger_container'))\n            }\n          }, (word: WordItem) => word.id)\n        }\n        .layoutWeight(1)\n        .width('100%')\n      }\n\n      Row({ space: AppTheme.SPACE_NORMAL }) {\n        Button('返回设置')\n          .layoutWeight(1)\n          .height(46)\n          .fontSize(15 * this.fontScale)\n          .backgroundColor($r('app.color.input_background'))\n          .fontColor($r('app.color.text_main'))\n          .onClick(() => {\n            this.backToConfig();\n          })\n        Button('再来一组')\n          .layoutWeight(1)\n          .height(46)\n          .fontSize(15 * this.fontScale)\n          .backgroundColor($r('app.color.primary'))\n          .fontColor($r('app.color.on_primary'))\n          .onClick(() => {\n            this.startQuiz();\n          })\n      }\n      .width('100%')\n      .margin({ top: 16 })\n      }\n      .width('100%')\n      .height('100%')\n      .padding(16)\n      .alignItems(HorizontalAlign.Center)\n    }\n    .width('100%')\n    .height('100%')\n    .borderRadius(AppTheme.CARD_RADIUS)\n    .backgroundColor($r('app.color.card_background'))\n    .shadow(AppTheme.cardShadow())\n    .clip(true)\n  }\n\n  build() {\n    Column() {\n      if (this.phase === 0) {\n        this.buildConfig()\n      } else if (this.phase === 1) {\n        Column() {\n          Progress({ value: this.quizProgress(), total: 1, type: ProgressType.Linear })\n            .width('100%')\n            .height(7)\n            .color($r('app.color.primary'))\n            .backgroundColor($r('app.color.primary_container'))\n            .borderRadius(999)\n            .margin({ bottom: 14 })\n          Scroll() {\n            this.buildQuestion()\n          }\n          .layoutWeight(1)\n          .width('100%')\n          .align(Alignment.Top)\n        }\n        .width('100%')\n        .height('100%')\n      } else {\n        this.buildResult()\n      }\n    }\n    .width('100%')\n    .height('100%')\n    .padding(AppTheme.PAGE_PADDING)\n    .backgroundColor($r('app.color.page_background'))\n  }\n}\n","src/ets/view/SettingsPage.ets":"// 设置页：主题三态、字体与目标、词书导入、数据重置\nimport { ConfigurationConstant, common } from '@kit.AbilityKit';\nimport { hilog } from '@kit.PerformanceAnalysisKit';\nimport { AppConstants } from '../common/AppConstants';\nimport { AppTheme } from '../common/AppTheme';\nimport { UserSettings } from '../model/WordModel';\nimport { StorageService } from '../service/StorageService';\nimport { WordBookService, ImportedBookData } from '../service/WordBookService';\n\nconst LOG_DOMAIN: number = 0x0006;\nconst TAG: string = 'SettingsPage';\n\ninterface ThemeTab {\n  mode: number;\n  label: string;\n}\n\ninterface ImportModeTab {\n  mode: number;\n  label: string;\n}\n\n@Component\nexport struct SettingsPage {\n  @Prop currentBookId: string = '';\n  @Prop @Watch('syncFromProps') themeMode: number = 0;\n  @Prop @Watch('syncFromProps') fontScale: number = 1.0;\n  @Prop @Watch('syncFromProps') dailyTarget: number = 20;\n  onSettingsChanged: (settings: UserSettings) => void = (settings: UserSettings) => {};\n  onBooksChanged: () => void = () => {};\n  onDataReset: () => void = () => {};\n\n  @State themeModeLocal: number = 0;\n  @State fontScaleLocal: number = 1.0;\n  @State dailyTargetLocal: number = 20;\n  @State importName: string = '';\n  @State importDescription: string = '';\n  @State importText: string = '';\n  @State importMode: number = 0;\n  @State importError: string = '';\n  @State importPreviewCount: number = 0;\n\n  private themeTabs: ThemeTab[] = [\n    { mode: 0, label: '跟随系统' },\n    { mode: 1, label: '浅色' },\n    { mode: 2, label: '深色' },\n  ];\n  private importModeTabs: ImportModeTab[] = [\n    { mode: 0, label: 'TXT' },\n    { mode: 1, label: 'JSON' },\n  ];\n\n  aboutToAppear(): void {\n    this.syncFromProps();\n  }\n\n  syncFromProps(): void {\n    this.themeModeLocal = this.themeMode;\n    this.fontScaleLocal = this.fontScale;\n    this.dailyTargetLocal = this.dailyTarget;\n  }\n\n  private persistSettings(): void {\n    const settings: UserSettings = {\n      themeMode: this.themeModeLocal,\n      fontScale: this.fontScaleLocal,\n      dailyTarget: this.dailyTargetLocal,\n      currentBookId: this.currentBookId,\n    };\n    this.onSettingsChanged(settings);\n  }\n\n  private applyThemeMode(mode: number): void {\n    this.themeModeLocal = mode;\n    try {\n      const context: common.UIAbilityContext =\n        this.getUIContext().getHostContext() as common.UIAbilityContext;\n      const appContext: common.ApplicationContext = context.getApplicationContext();\n      if (mode === 1) {\n        appContext.setColorMode(ConfigurationConstant.ColorMode.COLOR_MODE_LIGHT);\n      } else if (mode === 2) {\n        appContext.setColorMode(ConfigurationConstant.ColorMode.COLOR_MODE_DARK);\n      } else {\n        appContext.setColorMode(ConfigurationConstant.ColorMode.COLOR_MODE_NOT_SET);\n      }\n    } catch (err) {\n      hilog.error(LOG_DOMAIN, TAG, 'setColorMode failed: %{public}s', JSON.stringify(err));\n    }\n    this.persistSettings();\n  }\n\n  private parseImport(): ImportedBookData | undefined {\n    if (this.importText.trim().length === 0) {\n      return undefined;\n    }\n    const service: WordBookService = WordBookService.getInstance();\n    const id: string = service.sanitizeBookId(this.importName);\n    const name: string = this.importName.trim().length > 0 ? this.importName.trim() : '导入词书';\n    const description: string = this.importDescription.trim().length > 0\n      ? this.importDescription.trim() : '用户导入词表';\n    if (this.importMode === 0) {\n      return service.parseImportedText(this.importText, id, name, description);\n    }\n    return service.parseImportedJson(this.importText, id, name, description);\n  }\n\n  private updateImportPreview(): void {\n    try {\n      const data: ImportedBookData | undefined = this.parseImport();\n      this.importPreviewCount = data ? data.words.length : 0;\n      this.importError = data && data.words.length > 0 ? '' : '未解析到任何单词，请检查格式';\n    } catch (err) {\n      this.importPreviewCount = 0;\n      this.importError = '解析失败，请检查文本或 JSON 格式';\n    }\n  }\n\n  private async confirmImport(): Promise<void> {\n    try {\n      const data: ImportedBookData | undefined = this.parseImport();\n      if (!data || data.words.length === 0) {\n        this.importError = '未解析到任何单词，请检查格式';\n        return;\n      }\n      await WordBookService.getInstance().addImportedBook(data);\n      this.importError = '';\n      this.importText = '';\n      this.importName = '';\n      this.importDescription = '';\n      this.importPreviewCount = 0;\n      this.onBooksChanged();\n    } catch (err) {\n      this.importError = err instanceof Error ? err.message : '导入失败，请检查格式';\n    }\n  }\n\n  private confirmReset(): void {\n    this.getUIContext().showAlertDialog({\n      title: '重置学习数据',\n      message: '将清空全部学习进度、签到记录与导入词书，且不可恢复，确定继续吗？',\n      primaryButton: {\n        value: '取消',\n        action: () => {\n        },\n      },\n      secondaryButton: {\n        value: '确定重置',\n        fontColor: $r('app.color.danger'),\n        action: () => {\n          this.doReset();\n        },\n      },\n    });\n  }\n\n  private async doReset(): Promise<void> {\n    const ok: boolean = await StorageService.getInstance().resetAll();\n    if (!ok) {\n      this.getUIContext().showAlertDialog({\n        title: '重置失败',\n        message: '数据清空失败，请稍后重试',\n        confirm: {\n          value: '知道了',\n          action: () => {\n          },\n        },\n      });\n      return;\n    }\n    this.onDataReset();\n  }\n\n  build() {\n    Scroll() {\n      Column({ space: 12 }) {\n        Column() {\n          Text('基础设置')\n            .fontSize(22 * this.fontScaleLocal)\n            .fontWeight(FontWeight.Bold)\n            .fontColor($r('app.color.text_main'))\n            .width('100%')\n          Text('所有设置本地保存，重启后自动恢复')\n            .fontSize(13 * this.fontScaleLocal)\n            .fontColor($r('app.color.text_secondary'))\n            .margin({ top: 4, bottom: 14 })\n            .width('100%')\n\n          Row({ space: AppTheme.SPACE_SMALL }) {\n            ForEach(this.themeTabs, (tab: ThemeTab) => {\n              Button(tab.label)\n                .layoutWeight(1)\n                .height(40)\n                .fontSize(14 * this.fontScaleLocal)\n                .backgroundColor(this.themeModeLocal === tab.mode\n                  ? $r('app.color.primary') : $r('app.color.input_background'))\n                .fontColor(this.themeModeLocal === tab.mode\n                  ? $r('app.color.on_primary') : $r('app.color.text_main'))\n                .onClick(() => {\n                  this.applyThemeMode(tab.mode);\n                })\n            }, (tab: ThemeTab) => tab.label)\n          }\n          .width('100%')\n        }\n        .width('100%')\n        .padding(16)\n        .borderRadius(AppTheme.CARD_RADIUS)\n        .backgroundColor($r('app.color.card_background'))\n        .shadow(AppTheme.cardShadow())\n\n        Column() {\n          Row() {\n            Text('字体大小')\n              .fontSize(15 * this.fontScaleLocal)\n              .fontColor($r('app.color.text_main'))\n              .layoutWeight(1)\n            Text(this.fontScaleLocal.toFixed(1))\n              .fontSize(14 * this.fontScaleLocal)\n              .fontColor($r('app.color.primary'))\n          }\n          .width('100%')\n          Slider({\n            value: this.fontScaleLocal,\n            min: AppConstants.MIN_FONT_SCALE,\n            max: AppConstants.MAX_FONT_SCALE,\n            step: 0.1,\n          })\n            .blockColor($r('app.color.primary'))\n            .selectedColor($r('app.color.primary'))\n            .onChange((value: number) => {\n              this.fontScaleLocal = Math.round(value * 10) / 10;\n              this.persistSettings();\n            })\n        }\n        .width('100%')\n        .padding(16)\n        .borderRadius(AppTheme.CARD_RADIUS)\n        .backgroundColor($r('app.color.card_background'))\n        .shadow(AppTheme.cardShadow())\n\n        Column() {\n          Row() {\n            Text('每日目标词数')\n              .fontSize(15 * this.fontScaleLocal)\n              .fontColor($r('app.color.text_main'))\n              .layoutWeight(1)\n            Text(`${this.dailyTargetLocal}`)\n              .fontSize(14 * this.fontScaleLocal)\n              .fontColor($r('app.color.primary'))\n          }\n          .width('100%')\n          Slider({\n            value: this.dailyTargetLocal,\n            min: 1,\n            max: AppConstants.MAX_DAILY_TARGET,\n            step: 1,\n          })\n            .blockColor($r('app.color.primary'))\n            .selectedColor($r('app.color.primary'))\n            .onChange((value: number) => {\n              this.dailyTargetLocal = Math.round(value);\n              this.persistSettings();\n            })\n          Text('学习队列将按目标数安排复习词与新词')\n            .fontSize(12 * this.fontScaleLocal)\n            .fontColor($r('app.color.text_secondary'))\n            .margin({ top: 6 })\n            .width('100%')\n        }\n        .width('100%')\n        .padding(16)\n        .borderRadius(AppTheme.CARD_RADIUS)\n        .backgroundColor($r('app.color.card_background'))\n        .shadow(AppTheme.cardShadow())\n\n        Column() {\n          Text('导入词书')\n            .fontSize(16 * this.fontScaleLocal)\n            .fontWeight(FontWeight.Bold)\n            .fontColor($r('app.color.text_main'))\n            .width('100%')\n          Text('TXT 每行一条：word-meaning-phonetic-example；也支持 JSON 单词数组')\n            .fontSize(12 * this.fontScaleLocal)\n            .fontColor($r('app.color.text_secondary'))\n            .margin({ top: 6, bottom: 10 })\n            .width('100%')\n\n          Row({ space: AppTheme.SPACE_SMALL }) {\n            ForEach(this.importModeTabs, (tab: ImportModeTab) => {\n              Button(tab.label)\n                .layoutWeight(1)\n                .height(38)\n                .fontSize(14 * this.fontScaleLocal)\n                .backgroundColor(this.importMode === tab.mode\n                  ? $r('app.color.primary') : $r('app.color.input_background'))\n                .fontColor(this.importMode === tab.mode\n                  ? $r('app.color.on_primary') : $r('app.color.text_main'))\n                .onClick(() => {\n                  this.importMode = tab.mode;\n                  this.importError = '';\n                  this.updateImportPreview();\n                })\n            }, (tab: ImportModeTab) => tab.label)\n          }\n          .width('100%')\n          .margin({ bottom: 10 })\n\n          TextInput({ placeholder: '词书名称（可选）', text: this.importName })\n            .width('100%')\n            .height(44)\n            .fontSize(14 * this.fontScaleLocal)\n            .backgroundColor($r('app.color.input_background'))\n            .fontColor($r('app.color.text_main'))\n            .placeholderColor($r('app.color.text_muted'))\n            .borderRadius(12)\n            .margin({ bottom: 8 })\n            .onChange((value: string) => {\n              this.importName = value;\n            })\n          TextInput({ placeholder: '词书说明（可选）', text: this.importDescription })\n            .width('100%')\n            .height(44)\n            .fontSize(14 * this.fontScaleLocal)\n            .backgroundColor($r('app.color.input_background'))\n            .fontColor($r('app.color.text_main'))\n            .placeholderColor($r('app.color.text_muted'))\n            .borderRadius(12)\n            .margin({ bottom: 8 })\n            .onChange((value: string) => {\n              this.importDescription = value;\n            })\n          TextArea({\n            placeholder: this.importMode === 0\n              ? '每行一条：word-meaning-phonetic-example'\n              : '[{\"word\":\"...\",\"meaning\":\"...\"}]',\n            text: this.importText,\n          })\n            .width('100%')\n            .height(120)\n            .fontSize(14 * this.fontScaleLocal)\n            .backgroundColor($r('app.color.input_background'))\n            .fontColor($r('app.color.text_main'))\n            .placeholderColor($r('app.color.text_muted'))\n            .borderRadius(12)\n            .onChange((value: string) => {\n              this.importText = value;\n              this.updateImportPreview();\n            })\n\n          Row() {\n            Text(`预览解析：${this.importPreviewCount} 词`)\n              .fontSize(12 * this.fontScaleLocal)\n              .fontColor($r('app.color.text_secondary'))\n              .layoutWeight(1)\n            if (this.importError.length > 0) {\n              Text(this.importError)\n                .fontSize(12 * this.fontScaleLocal)\n                .fontColor($r('app.color.danger'))\n            }\n          }\n          .width('100%')\n          .margin({ top: 8 })\n\n          Button('导入并保存词书')\n            .width('100%')\n            .height(44)\n            .margin({ top: 12 })\n            .fontSize(15 * this.fontScaleLocal)\n            .backgroundColor($r('app.color.primary'))\n            .fontColor($r('app.color.on_primary'))\n            .onClick(() => {\n              this.confirmImport();\n            })\n        }\n        .width('100%')\n        .padding(16)\n        .borderRadius(AppTheme.CARD_RADIUS)\n        .backgroundColor($r('app.color.card_background'))\n        .shadow(AppTheme.cardShadow())\n\n        Button('重置全部学习数据')\n          .width('100%')\n          .height(46)\n          .fontSize(15 * this.fontScaleLocal)\n          .backgroundColor($r('app.color.danger_container'))\n          .fontColor($r('app.color.danger'))\n          .onClick(() => {\n            this.confirmReset();\n          })\n      }\n      .width('100%')\n      .padding(AppTheme.PAGE_PADDING)\n      .alignItems(HorizontalAlign.Start)\n    }\n    .width('100%')\n    .height('100%')\n    .backgroundColor($r('app.color.page_background'))\n    .align(Alignment.Top)\n  }\n}\n","src/ets/view/StatsPage.ets":"// 统计页：签到月历、近 7 天学习柱状图、核心学习指标、成就徽章\nimport { AppTheme } from '../common/AppTheme';\nimport {\n  CalendarCell,\n  DayLearnCount,\n  buildMonthCalendar,\n  currentBeijingYearMonth,\n  todayKey,\n} from '../common/DateUtils';\nimport { WordBookItem } from '../model/WordModel';\nimport { AchievementView } from '../service/AchievementService';\nimport { AchievementService } from '../service/AchievementService';\nimport { CheckInService } from '../service/CheckInService';\nimport { ReviewSchedulerService } from '../service/ReviewSchedulerService';\nimport { WordBookService } from '../service/WordBookService';\nimport { StatCard } from '../widget/StatCard';\n\ninterface WeekDay {\n  label: string;\n}\n\n@Component\nexport struct StatsPage {\n  @Prop fontScale: number = 1.0;\n  @Prop currentBookId: string = '';\n  @Prop @Watch('onRefreshTick') refreshTick: number = 0;\n\n  @State year: number = 2026;\n  @State month: number = 0;\n  @State monthCells: CalendarCell[] = [];\n  @State checkInKeys: string[] = [];\n  @State recent7: DayLearnCount[] = [];\n  @State totalCheckIns: number = 0;\n  @State streak: number = 0;\n  @State todayLearned: number = 0;\n  @State masteredCount: number = 0;\n  @State learningCount: number = 0;\n  @State dueCount: number = 0;\n  @State forgottenCount: number = 0;\n  @State totalWords: number = 0;\n  @State accuracyRate: number = 0;\n  @State totalReviews: number = 0;\n  @State bestStreak: number = 0;\n  @State avgPerDay: number = 0;\n  @State achievements: AchievementView[] = [];\n  @State unlockedCount: number = 0;\n\n  private weekDays: WeekDay[] = [\n    { label: '日' }, { label: '一' }, { label: '二' }, { label: '三' },\n    { label: '四' }, { label: '五' }, { label: '六' },\n  ];\n\n  aboutToAppear(): void {\n    this.loadData();\n  }\n\n  onRefreshTick(): void {\n    this.loadData();\n  }\n\n  private loadData(): void {\n    const scheduler: ReviewSchedulerService = ReviewSchedulerService.getInstance();\n    const ym: number[] = currentBeijingYearMonth();\n    this.year = ym[0];\n    this.month = ym[1];\n    this.reloadMonth();\n    this.recent7 = scheduler.getRecent7DaysCounts();\n    this.totalCheckIns = CheckInService.getInstance().getTotalCheckInDays();\n    this.streak = CheckInService.getInstance().getCurrentStreak();\n    this.todayLearned = ReviewSchedulerService.getInstance().getTodayLearnedCount();\n    this.masteredCount = ReviewSchedulerService.getInstance().getMasteredCount(this.currentBookId);\n    this.learningCount = scheduler.getLearningCount(this.currentBookId) + this.masteredCount;\n    this.dueCount = ReviewSchedulerService.getInstance().getDueCount(this.currentBookId);\n    this.forgottenCount = ReviewSchedulerService.getInstance().getForgottenCount(this.currentBookId);\n    const book: WordBookItem | undefined = WordBookService.getInstance().getBook(this.currentBookId);\n    this.totalWords = book ? book.words.length : 0;\n    this.accuracyRate = scheduler.getAccuracyRate();\n    this.totalReviews = scheduler.getTotalReviewCount();\n    this.bestStreak = CheckInService.getInstance().getBestStreak();\n    this.avgPerDay = scheduler.getAveragePerDay();\n    this.achievements = AchievementService.getInstance().getAllAchievements();\n    this.unlockedCount = AchievementService.getInstance().getUnlockedCount();\n  }\n\n  private reloadMonth(): void {\n    this.monthCells = buildMonthCalendar(this.year, this.month);\n    this.checkInKeys = CheckInService.getInstance().getMonthCheckInKeys(this.year, this.month);\n  }\n\n  private shiftMonth(delta: number): void {\n    let nextMonth: number = this.month + delta;\n    let nextYear: number = this.year;\n    if (nextMonth < 0) {\n      nextMonth = 11;\n      nextYear -= 1;\n    } else if (nextMonth > 11) {\n      nextMonth = 0;\n      nextYear += 1;\n    }\n    this.month = nextMonth;\n    this.year = nextYear;\n    this.reloadMonth();\n  }\n\n  private isCheckedIn(cell: CalendarCell): boolean {\n    return this.checkInKeys.indexOf(cell.dateKey) >= 0;\n  }\n\n  private maxRecentCount(): number {\n    let max: number = 0;\n    for (let i: number = 0; i < this.recent7.length; i++) {\n      if (this.recent7[i].count > max) {\n        max = this.recent7[i].count;\n      }\n    }\n    return max;\n  }\n\n  private barHeight(count: number): number {\n    const max: number = this.maxRecentCount();\n    if (max <= 0) {\n      return 4;\n    }\n    const height: number = (count / max) * 90;\n    return height < 4 ? 4 : height;\n  }\n\n  private masteredProgress(): number {\n    return this.totalWords === 0 ? 0 : Math.min(this.learningCount / this.totalWords, 1);\n  }\n\n  @Builder\n  buildCalendarCell(cell: CalendarCell) {\n    Column() {\n      Text(`${cell.day}`)\n        .fontSize(13 * this.fontScale)\n        .fontColor(!cell.inMonth ? $r('app.color.text_muted') :\n          (this.isCheckedIn(cell) ? $r('app.color.success') :\n            (cell.isToday ? $r('app.color.primary') : $r('app.color.text_main'))))\n        .fontWeight(cell.isToday || this.isCheckedIn(cell) ? FontWeight.Bold : FontWeight.Normal)\n    }\n    .width('100%')\n    .aspectRatio(1.4)\n    .justifyContent(FlexAlign.Center)\n    .borderRadius(8)\n    .backgroundColor(this.isCheckedIn(cell) ? $r('app.color.success_container') :\n      (cell.isToday ? $r('app.color.primary_container') : Color.Transparent))\n    .border({\n      width: cell.isToday ? 1 : 0,\n      color: $r('app.color.primary'),\n    })\n  }\n\n  build() {\n    Scroll() {\n      Column() {\n      Row() {\n        Column() {\n          Text('学习数据看板')\n            .fontSize(22 * this.fontScale)\n            .fontWeight(FontWeight.Bold)\n            .fontColor($r('app.color.text_main'))\n          Text('打卡日历、学习趋势与词书掌握情况')\n            .fontSize(13 * this.fontScale)\n            .fontColor($r('app.color.text_secondary'))\n            .margin({ top: 4 })\n        }\n        .layoutWeight(1)\n        .alignItems(HorizontalAlign.Start)\n\n        Column() {\n          Image($r('app.media.mascot_owl'))\n            .width(34)\n            .height(34)\n        }\n        .width(48)\n        .height(48)\n        .borderRadius(999)\n        .backgroundColor($r('app.color.accent_purple_container'))\n        .justifyContent(FlexAlign.Center)\n      }\n      .width('100%')\n      .margin({ bottom: 14 })\n\n        Row() {\n          StatCard({\n            title: '累计签到',\n            value: `${this.totalCheckIns}`,\n            hint: '天',\n            accent: 'purple',\n            fontScale: this.fontScale,\n          })\n          StatCard({\n            title: '连续签到',\n            value: `${this.streak}`,\n            hint: '天',\n            accent: 'success',\n            fontScale: this.fontScale,\n          })\n          StatCard({\n            title: '今日学习',\n            value: `${this.todayLearned}`,\n            hint: '词',\n            accent: 'teal',\n            fontScale: this.fontScale,\n          })\n        }\n        .width('100%')\n        .justifyContent(FlexAlign.SpaceBetween)\n        .margin({ bottom: 12 })\n\n        Row() {\n          StatCard({\n            title: '已学习',\n            value: `${this.learningCount}`,\n            hint: `共 ${this.totalWords} 词`,\n            accent: 'success',\n            showProgress: true,\n            progress: this.masteredProgress(),\n            fontScale: this.fontScale,\n          })\n          StatCard({\n            title: '待复习',\n            value: `${this.dueCount}`,\n            hint: '今日到期',\n            accent: 'danger',\n            fontScale: this.fontScale,\n          })\n          StatCard({\n            title: '遗忘词',\n            value: `${this.forgottenCount}`,\n            hint: '超7天未复习',\n            accent: 'pink',\n            fontScale: this.fontScale,\n          })\n        }\n        .width('100%')\n        .justifyContent(FlexAlign.SpaceBetween)\n        .margin({ bottom: 14 })\n\n        Row() {\n          StatCard({\n            title: '正确率',\n            value: `${this.accuracyRate}%`,\n            hint: '复习判定准确率',\n            accent: 'teal',\n            fontScale: this.fontScale,\n          })\n          StatCard({\n            title: '累计复习',\n            value: `${this.totalReviews}`,\n            hint: '次',\n            accent: 'purple',\n            fontScale: this.fontScale,\n          })\n          StatCard({\n            title: '最高连续',\n            value: `${this.bestStreak}`,\n            hint: `日均 ${this.avgPerDay} 词`,\n            accent: 'warning',\n            fontScale: this.fontScale,\n          })\n        }\n        .width('100%')\n        .justifyContent(FlexAlign.SpaceBetween)\n        .margin({ bottom: 14 })\n\n        Column() {\n          Row() {\n            Button('<')\n              .fontSize(14 * this.fontScale)\n              .height(32)\n              .width(44)\n              .backgroundColor($r('app.color.input_background'))\n              .fontColor($r('app.color.text_main'))\n              .onClick(() => {\n                this.shiftMonth(-1);\n              })\n            Text(`${this.year} 年 ${this.month + 1} 月`)\n              .fontSize(16 * this.fontScale)\n              .fontWeight(FontWeight.Bold)\n              .fontColor($r('app.color.text_main'))\n              .layoutWeight(1)\n              .textAlign(TextAlign.Center)\n            Button('>')\n              .fontSize(14 * this.fontScale)\n              .height(32)\n              .width(44)\n              .backgroundColor($r('app.color.input_background'))\n              .fontColor($r('app.color.text_main'))\n              .onClick(() => {\n                this.shiftMonth(1);\n              })\n          }\n          .width('100%')\n          .margin({ bottom: 10 })\n\n          Row() {\n            ForEach(this.weekDays, (day: WeekDay) => {\n              Text(day.label)\n                .layoutWeight(1)\n                .textAlign(TextAlign.Center)\n                .fontSize(12 * this.fontScale)\n                .fontColor($r('app.color.text_muted'))\n            }, (day: WeekDay) => day.label)\n          }\n          .width('100%')\n          .margin({ bottom: 6 })\n\n          Grid() {\n            ForEach(this.monthCells, (cell: CalendarCell) => {\n              GridItem() {\n                this.buildCalendarCell(cell)\n              }\n            }, (cell: CalendarCell) => cell.dateKey)\n          }\n          .columnsTemplate('1fr 1fr 1fr 1fr 1fr 1fr 1fr')\n          .rowsTemplate('1fr 1fr 1fr 1fr 1fr 1fr')\n          .columnsGap(4)\n          .rowsGap(4)\n          .width('100%')\n          .height(240)\n        }\n        .width('100%')\n        .padding(16)\n        .borderRadius(AppTheme.CARD_RADIUS)\n        .backgroundColor($r('app.color.card_background'))\n        .shadow(AppTheme.cardShadow())\n        .margin({ bottom: 14 })\n\n        Column() {\n          Text('近 7 天学习量')\n            .fontSize(16 * this.fontScale)\n            .fontWeight(FontWeight.Bold)\n            .fontColor($r('app.color.text_main'))\n            .width('100%')\n            .margin({ bottom: 14 })\n          Row() {\n            ForEach(this.recent7, (day: DayLearnCount) => {\n              Column() {\n                Text(`${day.count}`)\n                  .fontSize(11 * this.fontScale)\n                  .fontColor($r('app.color.text_secondary'))\n                  .margin({ bottom: 4 })\n                Column()\n                  .width(22)\n                  .height(this.barHeight(day.count))\n                  .borderRadius(6)\n                  .backgroundColor(day.dateKey === todayKey()\n                    ? $r('app.color.primary')\n                    : (day.count > 0 ? $r('app.color.chart_bar_alt') : $r('app.color.chart_bar')))\n                Text(day.label)\n                  .fontSize(11 * this.fontScale)\n                  .fontColor($r('app.color.text_muted'))\n                  .margin({ top: 6 })\n              }\n              .layoutWeight(1)\n              .height(130)\n              .justifyContent(FlexAlign.End)\n            }, (day: DayLearnCount) => day.dateKey)\n          }\n          .width('100%')\n          .height(130)\n          .alignItems(VerticalAlign.Center)\n        }\n        .width('100%')\n        .padding(16)\n        .borderRadius(AppTheme.CARD_RADIUS)\n        .backgroundColor($r('app.color.card_background'))\n        .shadow(AppTheme.cardShadow())\n        .margin({ bottom: 14 })\n\n        Column() {\n          Row() {\n            Text('成就徽章')\n              .fontSize(16 * this.fontScale)\n              .fontWeight(FontWeight.Bold)\n              .fontColor($r('app.color.text_main'))\n              .layoutWeight(1)\n            Text(`${this.unlockedCount}/${this.achievements.length}`)\n              .fontSize(13 * this.fontScale)\n              .fontColor($r('app.color.accent_purple'))\n          }\n          .width('100%')\n          .margin({ bottom: 12 })\n\n          Grid() {\n            ForEach(this.achievements, (item: AchievementView) => {\n              GridItem() {\n                Column({ space: 6 }) {\n                  Text(item.def.icon)\n                    .fontSize(28)\n                  Text(item.def.title)\n                    .fontSize(11 * this.fontScale)\n                    .fontWeight(FontWeight.Bold)\n                    .fontColor(item.unlocked\n                      ? $r('app.color.text_main') : $r('app.color.text_muted'))\n                  Text(item.def.description)\n                    .fontSize(9 * this.fontScale)\n                    .fontColor(item.unlocked\n                      ? $r('app.color.text_secondary') : $r('app.color.text_muted'))\n                }\n                .width('100%')\n                .padding({ top: 10, bottom: 10, left: 4, right: 4 })\n                .borderRadius(14)\n                .backgroundColor(item.unlocked\n                  ? $r('app.color.accent_purple_container') : $r('app.color.input_background'))\n                .opacity(item.unlocked ? 1 : 0.5)\n              }\n            }, (item: AchievementView) => item.def.id)\n          }\n          .columnsTemplate('1fr 1fr 1fr')\n          .columnsGap(8)\n          .rowsGap(8)\n          .width('100%')\n        }\n        .width('100%')\n        .padding(16)\n        .borderRadius(AppTheme.CARD_RADIUS)\n        .backgroundColor($r('app.color.card_background'))\n        .shadow(AppTheme.cardShadow())\n      }\n      .width('100%')\n      .padding(AppTheme.PAGE_PADDING)\n      .alignItems(HorizontalAlign.Start)\n    }\n    .width('100%')\n    .height('100%')\n    .backgroundColor($r('app.color.page_background'))\n    .align(Alignment.Top)\n  }\n}\n","src/ets/view/StudyPage.ets":"// 背词页：艾宾浩斯学习队列（到期复习优先 + 新词补足），卡片翻转与判定\nimport { AppTheme } from '../common/AppTheme';\nimport { WordItem, createWord } from '../model/WordModel';\nimport { ReviewSchedulerService } from '../service/ReviewSchedulerService';\nimport { TtsService } from '../service/TtsService';\nimport { WordCard } from '../widget/WordCard';\n\n@Component\nexport struct StudyPage {\n  @Prop fontScale: number = 1.0;\n  @Prop dailyTarget: number = 20;\n  @Prop @Watch('onBookChanged') currentBookId: string = '';\n  @Prop @Watch('onTickChanged') refreshTick: number = 0;\n  onDataChanged: () => void = () => {};\n\n  @State queue: WordItem[] = [];\n  @State currentIndex: number = 0;\n  @State showAnswer: boolean = false;\n  @State finished: boolean = false;\n  @State sessionLearned: number = 0;\n  @State processing: boolean = false;\n  @State currentWordState: WordItem = createWord('', '', '', '暂无单词', '');\n\n  aboutToAppear(): void {\n    this.loadQueue();\n  }\n\n  onBookChanged(): void {\n    this.loadQueue();\n  }\n\n  // 数据刷新时，仅在尚未开始本组学习时重建队列；学习中途与完成态均不自动重载，\n  // 避免完成总结页被刷新冲掉、学习进度被重置\n  onTickChanged(): void {\n    if (!this.finished && this.sessionLearned === 0) {\n      this.loadQueue();\n    }\n  }\n\n  private loadQueue(): void {\n    this.queue = ReviewSchedulerService.getInstance().getStudyQueue(this.currentBookId, this.dailyTarget);\n    this.currentIndex = 0;\n    this.showAnswer = false;\n    this.finished = false;\n    this.sessionLearned = 0;\n    this.processing = false;\n    this.syncCurrentWord();\n  }\n\n  private syncCurrentWord(): void {\n    if (this.queue.length > 0 && this.currentIndex < this.queue.length) {\n      this.currentWordState = this.queue[this.currentIndex];\n    } else {\n      this.currentWordState = createWord('', '', '', '暂无单词', '');\n    }\n  }\n\n  private speakWord(): void {\n    if (this.currentWordState.word.length > 0) {\n      TtsService.getInstance().speak(this.currentWordState.word);\n    }\n  }\n\n  private async markWord(wasCorrect: boolean): Promise<void> {\n    // 重入守卫：持久化 await 期间禁止重复点击，防止同词处理两次导致等级污染与跳词\n    if (this.processing || this.finished || this.currentWordState.word.length === 0) {\n      return;\n    }\n    this.processing = true;\n    try {\n      await ReviewSchedulerService.getInstance()\n        .processReview(this.currentBookId, this.currentWordState, wasCorrect);\n      this.sessionLearned += 1;\n      this.showAnswer = false;\n      if (this.currentIndex + 1 >= this.queue.length) {\n        this.finished = true;\n        this.syncCurrentWord();\n      } else {\n        this.currentIndex += 1;\n        this.syncCurrentWord();\n      }\n      this.onDataChanged();\n    } catch (err) {\n      // 服务层已记录日志并吞掉异常，此处兜底防止未处理 Promise rejection\n    } finally {\n      this.processing = false;\n    }\n  }\n\n  private progressValue(): number {\n    return this.queue.length === 0 ? 0 : Math.min(this.currentIndex / this.queue.length, 1);\n  }\n\n  @Builder\n  buildFinished() {\n    Stack() {\n      Column()\n        .width(80)\n        .height(80)\n        .borderRadius(999)\n        .backgroundColor(this.sessionLearned === 0\n          ? $r('app.color.primary_container') : $r('app.color.warning_container'))\n        .opacity(0.18)\n        .position({ x: -24, y: -26 })\n        .hitTestBehavior(HitTestMode.None)\n      Column()\n        .width(54)\n        .height(54)\n        .borderRadius(999)\n        .backgroundColor(this.sessionLearned === 0\n          ? $r('app.color.accent_teal_container') : $r('app.color.success_container'))\n        .opacity(0.18)\n        .position({ x: 268, y: 150 })\n        .hitTestBehavior(HitTestMode.None)\n\n      Column() {\n        Column() {\n          Image(this.sessionLearned === 0 ? $r('app.media.mascot_owl') : $r('app.media.mascot_trophy'))\n            .width(64)\n            .height(64)\n        }\n        .width(96)\n        .height(96)\n        .borderRadius(999)\n        .backgroundColor(this.sessionLearned === 0\n          ? $r('app.color.primary_container') : $r('app.color.warning_container'))\n        .justifyContent(FlexAlign.Center)\n\n        Text(this.sessionLearned === 0 ? '当前没有待学单词' : '本组学习完成')\n          .fontSize(26 * this.fontScale)\n          .fontWeight(FontWeight.Bold)\n          .fontColor($r('app.color.text_main'))\n          .margin({ top: 16 })\n        Text(this.sessionLearned === 0\n          ? '当前词书单词已全部掌握，或词书为空，请切换词书'\n          : `本轮共学习 ${this.sessionLearned} 个单词，继续保持！`)\n          .fontSize(14 * this.fontScale)\n          .fontColor($r('app.color.text_secondary'))\n          .margin({ top: 10 })\n        Row({ space: AppTheme.SPACE_NORMAL }) {\n          Button('再来一组')\n            .layoutWeight(1)\n            .height(44)\n            .backgroundColor($r('app.color.primary'))\n            .fontColor($r('app.color.on_primary'))\n            .onClick(() => {\n              this.loadQueue();\n            })\n        }\n        .width('100%')\n        .margin({ top: 20 })\n      }\n      .width('100%')\n      .padding(24)\n    }\n    .width('100%')\n    .borderRadius(AppTheme.CARD_RADIUS)\n    .backgroundColor($r('app.color.card_background'))\n    .shadow(AppTheme.cardShadow())\n    .clip(true)\n  }\n\n  build() {\n    Column() {\n      Row() {\n        Column() {\n          Text('卡片式背词')\n            .fontSize(22 * this.fontScale)\n            .fontWeight(FontWeight.Bold)\n            .fontColor($r('app.color.text_main'))\n          Text('复习词优先，认识升级 / 不认识当日重现')\n            .fontSize(13 * this.fontScale)\n            .fontColor($r('app.color.text_secondary'))\n            .margin({ top: 4 })\n        }\n        .layoutWeight(1)\n        .alignItems(HorizontalAlign.Start)\n\n        Text(`${Math.min(this.currentIndex + 1, this.queue.length)}/${this.queue.length}`)\n          .fontSize(12 * this.fontScale)\n          .fontColor($r('app.color.primary'))\n          .padding({ left: 10, right: 10, top: 6, bottom: 6 })\n          .borderRadius(999)\n          .backgroundColor($r('app.color.primary_container'))\n      }\n      .width('100%')\n      .margin({ bottom: 16 })\n\n      Progress({ value: this.progressValue(), total: 1, type: ProgressType.Linear })\n        .width('100%')\n        .height(7)\n        .color($r('app.color.primary'))\n        .backgroundColor($r('app.color.primary_container'))\n        .borderRadius(999)\n        .margin({ bottom: 14 })\n\n      if (this.finished || this.queue.length === 0) {\n        Column() {\n          this.buildFinished()\n        }\n        .layoutWeight(1)\n        .justifyContent(FlexAlign.Center)\n        .width('100%')\n      } else {\n        Column() {\n          WordCard({\n            word: this.currentWordState.word,\n            phonetic: this.currentWordState.phonetic,\n            meaning: this.currentWordState.meaning,\n            example: this.currentWordState.example,\n            showAnswer: this.showAnswer,\n            fontScale: this.fontScale,\n            onFlip: () => {\n              this.showAnswer = !this.showAnswer;\n            },\n            onSpeak: () => {\n              this.speakWord();\n            },\n          })\n\n          Row({ space: AppTheme.SPACE_NORMAL }) {\n            Button('不认识')\n              .layoutWeight(1)\n              .height(48)\n              .fontSize(16 * this.fontScale)\n              .backgroundColor($r('app.color.danger_container'))\n              .fontColor($r('app.color.danger'))\n              .enabled(!this.processing)\n              .onClick(() => {\n                this.markWord(false);\n              })\n            Button('认识')\n              .layoutWeight(1)\n              .height(48)\n              .fontSize(16 * this.fontScale)\n              .backgroundColor($r('app.color.success_container'))\n              .fontColor($r('app.color.success'))\n              .enabled(!this.processing)\n              .onClick(() => {\n                this.markWord(true);\n              })\n          }\n          .width('100%')\n          .margin({ top: 16 })\n        }\n        .layoutWeight(1)\n        .width('100%')\n      }\n    }\n    .width('100%')\n    .height('100%')\n    .padding(AppTheme.PAGE_PADDING)\n    .backgroundColor($r('app.color.page_background'))\n  }\n}\n","src/ets/widget/BookItemCard.ets":"// 词书条目卡片：名称、说明、词数与掌握进度、选中态\nimport { AppTheme } from '../common/AppTheme';\n\n@Component\nexport struct BookItemCard {\n  @Prop bookName: string = '';\n  @Prop description: string = '';\n  @Prop wordCount: number = 0;\n  @Prop masteredCount: number = 0;\n  @Prop isSelected: boolean = false;\n  @Prop fontScale: number = 1.0;\n  onSelect: () => void = () => {};\n\n  private progressValue(): number {\n    return this.wordCount === 0 ? 0 : Math.min(this.masteredCount / this.wordCount, 1);\n  }\n\n  build() {\n    Row({ space: 12 }) {\n      Column() {\n        Image($r('app.media.icon_book'))\n          .width(26)\n          .height(26)\n      }\n      .width(46)\n      .height(46)\n      .borderRadius(14)\n      .backgroundColor(this.isSelected ? $r('app.color.accent_purple_container') : $r('app.color.primary_container'))\n      .justifyContent(FlexAlign.Center)\n\n      Column() {\n        Text(this.bookName)\n          .fontSize(15 * this.fontScale)\n          .fontWeight(FontWeight.Bold)\n          .fontColor($r('app.color.text_main'))\n        Text(this.description)\n          .fontSize(12 * this.fontScale)\n          .fontColor($r('app.color.text_secondary'))\n          .margin({ top: 2 })\n        Row() {\n          Text(`共 ${this.wordCount} 词 · 已掌握 ${this.masteredCount}`)\n            .fontSize(11 * this.fontScale)\n            .fontColor($r('app.color.text_muted'))\n            .layoutWeight(1)\n          Text(this.isSelected ? '当前使用' : '点击切换')\n            .fontSize(12 * this.fontScale)\n            .fontColor(this.isSelected ? $r('app.color.primary') : $r('app.color.text_secondary'))\n        }\n        .width('100%')\n        .margin({ top: 8 })\n        Progress({ value: this.progressValue(), total: 1, type: ProgressType.Linear })\n          .margin({ top: 6 })\n          .height(4)\n          .color($r('app.color.success'))\n          .backgroundColor($r('app.color.divider'))\n      }\n      .layoutWeight(1)\n      .alignItems(HorizontalAlign.Start)\n    }\n    .padding(14)\n    .margin({ bottom: AppTheme.SPACE_NORMAL })\n    .borderRadius(16)\n    .backgroundColor(this.isSelected ? $r('app.color.primary_container') : $r('app.color.card_background'))\n    .shadow(AppTheme.cardShadow())\n    .onClick(() => {\n      this.onSelect();\n    })\n  }\n}\n","src/ets/widget/CheckInButton.ets":"// 签到按钮：未签到可点击，已签到显示成功态\n@Component\nexport struct CheckInButton {\n  @Prop checkedIn: boolean = false;\n  @Prop fontScale: number = 1.0;\n  onCheckIn: () => void = () => {};\n\n  build() {\n    Button(this.checkedIn ? '已签到' : '签到')\n      .layoutWeight(1)\n      .height(44)\n      .fontSize(15 * this.fontScale)\n      .fontWeight(this.checkedIn ? FontWeight.Bold : FontWeight.Normal)\n      .fontColor($r('app.color.on_primary'))\n      .backgroundColor(this.checkedIn ? $r('app.color.success') : $r('app.color.accent_orange'))\n      .padding({ left: 8, right: 8 })\n      .enabled(!this.checkedIn)\n      .onClick(() => {\n        this.onCheckIn();\n      })\n  }\n}\n","src/ets/widget/StatCard.ets":"// 统计指标卡片：标题、数值、可选进度条，右上角同色系装饰圆\nimport { AppTheme } from '../common/AppTheme';\n\n@Component\nexport struct StatCard {\n  @Prop title: string = '';\n  @Prop value: string = '';\n  @Prop hint: string = '';\n  @Prop accent: string = 'primary';\n  @Prop showProgress: boolean = false;\n  @Prop progress: number = 0;\n  @Prop fontScale: number = 1.0;\n\n  private accentColor(): Resource {\n    if (this.accent === 'success') {\n      return $r('app.color.success');\n    }\n    if (this.accent === 'warning') {\n      return $r('app.color.warning');\n    }\n    if (this.accent === 'danger') {\n      return $r('app.color.danger');\n    }\n    if (this.accent === 'purple') {\n      return $r('app.color.accent_purple');\n    }\n    if (this.accent === 'teal') {\n      return $r('app.color.accent_teal');\n    }\n    if (this.accent === 'pink') {\n      return $r('app.color.accent_pink');\n    }\n    return $r('app.color.primary');\n  }\n\n  private trackColor(): Resource {\n    if (this.accent === 'success') {\n      return $r('app.color.success_container');\n    }\n    if (this.accent === 'warning') {\n      return $r('app.color.warning_container');\n    }\n    if (this.accent === 'danger') {\n      return $r('app.color.danger_container');\n    }\n    if (this.accent === 'purple') {\n      return $r('app.color.accent_purple_container');\n    }\n    if (this.accent === 'teal') {\n      return $r('app.color.accent_teal_container');\n    }\n    if (this.accent === 'pink') {\n      return $r('app.color.accent_pink_container');\n    }\n    return $r('app.color.primary_container');\n  }\n\n  build() {\n    Stack({ alignContent: Alignment.TopEnd }) {\n      Column() {\n        Row({ space: 6 }) {\n          Column()\n            .width(8)\n            .height(8)\n            .borderRadius(999)\n            .backgroundColor(this.accentColor())\n          Text(this.title)\n            .fontSize(12 * this.fontScale)\n            .fontColor($r('app.color.text_secondary'))\n        }\n        .width('100%')\n\n        Text(this.value)\n          .fontSize(24 * this.fontScale)\n          .fontWeight(FontWeight.Bold)\n          .fontColor(this.accentColor())\n          .margin({ top: 6 })\n        if (this.showProgress) {\n          Progress({ value: this.progress, total: 1, type: ProgressType.Linear })\n            .margin({ top: 10 })\n            .width('100%')\n            .height(6)\n            .color(this.accentColor())\n            .backgroundColor(this.trackColor())\n        }\n        if (this.hint.length > 0) {\n          Text(this.hint)\n            .fontSize(11 * this.fontScale)\n            .fontColor($r('app.color.text_secondary'))\n            .margin({ top: 6 })\n        }\n      }\n      .width('100%')\n      .alignItems(HorizontalAlign.Start)\n\n      Column()\n        .width(40)\n        .height(40)\n        .borderRadius(999)\n        .backgroundColor(this.trackColor())\n        .opacity(0.15)\n        .margin({ top: -8, right: -8 })\n        .hitTestBehavior(HitTestMode.None)\n    }\n    .width('31%')\n    .padding(14)\n    .borderRadius(AppTheme.CARD_RADIUS)\n    .backgroundColor($r('app.color.card_background'))\n    .shadow(AppTheme.cardShadow())\n    .clip(true)\n  }\n}\n","src/ets/widget/WordCard.ets":"// 单词翻转卡片：正面显示单词与音标，反面显示释义与例句\nimport { AppTheme } from '../common/AppTheme';\n\n@Component\nexport struct WordCard {\n  @Prop word: string = '';\n  @Prop phonetic: string = '';\n  @Prop meaning: string = '';\n  @Prop example: string = '';\n  @Prop showAnswer: boolean = false;\n  @Prop fontScale: number = 1.0;\n  onFlip: () => void = () => {};\n  onSpeak: () => void = () => {};\n\n  build() {\n    Column() {\n      if (this.showAnswer) {\n        Row()\n          .width(36)\n          .height(4)\n          .borderRadius(999)\n          .backgroundColor($r('app.color.success'))\n          .margin({ bottom: 14 })\n        Text(this.meaning)\n          .fontSize(28 * this.fontScale)\n          .fontWeight(FontWeight.Bold)\n          .textAlign(TextAlign.Center)\n          .fontColor($r('app.color.success'))\n        Text(this.example)\n          .fontSize(13 * this.fontScale)\n          .fontColor($r('app.color.text_secondary'))\n          .margin({ top: 14 })\n          .textAlign(TextAlign.Center)\n        Text('点击卡片返回单词')\n          .fontSize(12 * this.fontScale)\n          .fontColor($r('app.color.text_muted'))\n          .margin({ top: 16 })\n      } else {\n        Row({ space: 5 }) {\n          Column()\n            .width(7)\n            .height(7)\n            .borderRadius(999)\n            .backgroundColor($r('app.color.accent_teal'))\n          Column()\n            .width(7)\n            .height(7)\n            .borderRadius(999)\n            .backgroundColor($r('app.color.accent_orange'))\n          Column()\n            .width(7)\n            .height(7)\n            .borderRadius(999)\n            .backgroundColor($r('app.color.accent_pink'))\n        }\n        .width('100%')\n        .margin({ bottom: 12 })\n        .justifyContent(FlexAlign.Start)\n\n        Row() {\n          Text(this.word)\n            .fontSize(30 * this.fontScale)\n            .fontWeight(FontWeight.Bold)\n            .fontColor($r('app.color.text_main'))\n            .layoutWeight(1)\n            .textAlign(TextAlign.Center)\n          Button('朗读')\n            .fontSize(12 * this.fontScale)\n            .height(32)\n            .padding({ left: 10, right: 10 })\n            .backgroundColor($r('app.color.primary_container'))\n            .fontColor($r('app.color.primary'))\n            .hitTestBehavior(HitTestMode.Block)\n            .onClick(() => {\n              this.onSpeak();\n            })\n        }\n        .width('100%')\n        .justifyContent(FlexAlign.Center)\n\n        Text(this.phonetic)\n          .fontSize(14 * this.fontScale)\n          .fontColor($r('app.color.text_secondary'))\n          .margin({ top: 8 })\n        Text('点击卡片查看释义')\n          .fontSize(13 * this.fontScale)\n          .fontColor($r('app.color.text_muted'))\n          .margin({ top: 14 })\n      }\n    }\n    .width('100%')\n    .padding(24)\n    .borderRadius(22)\n    .backgroundColor($r('app.color.card_background'))\n    .shadow(AppTheme.cardShadow())\n    .onClick(() => {\n      this.onFlip();\n    })\n  }\n}\n","src/module.json5":"{\r\n  \"module\": {\r\n    \"name\": \"entry\",\r\n    \"type\": \"entry\",\r\n    \"description\": \"$string:module_desc\",\r\n    \"mainElement\": \"EntryAbility\",\r\n    \"deviceTypes\": [\r\n      \"phone\"\r\n    ],\r\n    \"deliveryWithInstall\": true,\r\n    \"installationFree\": false,\r\n    \"pages\": \"$profile:main_pages\",\r\n    \"abilities\": [\r\n      {\r\n        \"name\": \"EntryAbility\",\r\n        \"srcEntry\": \"./ets/entryability/EntryAbility.ets\",\r\n        \"description\": \"$string:EntryAbility_desc\",\r\n        \"icon\": \"$media:layered_image\",\r\n        \"label\": \"$string:EntryAbility_label\",\r\n        \"startWindowIcon\": \"$media:startIcon\",\r\n        \"startWindowBackground\": \"$color:start_window_background\",\r\n        \"exported\": true,\r\n        \"skills\": [\r\n          {\r\n            \"entities\": [\r\n              \"entity.system.home\"\r\n            ],\r\n            \"actions\": [\r\n              \"ohos.want.action.home\"\r\n            ]\r\n          }\r\n        ]\r\n      }\r\n    ],\r\n    \"extensionAbilities\": [\r\n      {\r\n        \"name\": \"EntryBackupAbility\",\r\n        \"srcEntry\": \"./ets/entrybackupability/EntryBackupAbility.ets\",\r\n        \"type\": \"backup\",\r\n        \"exported\": false,\r\n        \"metadata\": [\r\n          {\r\n            \"name\": \"ohos.extension.backup\",\r\n            \"resource\": \"$profile:backup_config\"\r\n          }\r\n        ]\r\n      }\r\n    ]\r\n  }\r\n}"};